-- ============================================================
-- REFYN — QUESTION BANK SEED (part 2 of 4)
-- Source: Refyn_Question_Intake_8_fixed.xlsx, sheet "Question_Intake"
-- Rows 201-400 of 613
--
-- Run AFTER master_setup.sql + seed_taxonomy.sql, in the Supabase SQL Editor.
-- Idempotent: re-running skips rows already present (exam_id, external_id).
--
-- Transforms applied to the sheet data:
--   * question_type / correct_answer (MCQ) lowercased to match existing seeds
--   * calculation_level 'hard'->'high', 'easy'->'low' (CHECK allows low/medium/high)
--   * TITA rows get NULL options
--   * 39 solutions that were left mid-draft in the sheet were re-derived and
--     rewritten; answer keys were verified unchanged.
--   * subtopic resolved by concept_code; a row whose code is missing from
--     subtopics would be skipped -- the verification query at the end of
--     part 4 reports the final count.
-- ============================================================

INSERT INTO questions (
  exam_id, subtopic_id,
  external_id, year, slot, source, is_pyq,
  question_text, question_type,
  option_a, option_b, option_c, option_d,
  correct_answer, solution, alternate_solution,
  difficulty, calculation_level, logic_level,
  expected_time_seconds, common_mistakes
)
SELECT
  (SELECT id FROM exams WHERE slug = 'cat'), s.id,
  v.external_id, v.year, v.slot, v.source, v.is_pyq,
  v.question_text, v.question_type,
  v.option_a, v.option_b, v.option_c, v.option_d,
  v.correct_answer, v.solution, v.alternate_solution,
  v.difficulty, v.calculation_level, v.logic_level,
  v.expected_time_seconds, v.common_mistakes
FROM (VALUES
  ('CAT2022_QA_S3_02', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'ALG_QUAD_ROOT', 'Suppose k is any integer such that the equation 2x^2+kx+5=0 has no real roots and the equation x^2+(k-5)x+1=0 has two distinct real roots for x. Then the number of possible values of k is', 'mcq', '9', '7', '8', '13', 'a', 'No real roots for the first equation needs k^2<40, i.e. k in (-sqrt40, sqrt40). Two distinct real roots for the second needs (k-5)^2>4, i.e. k<3 or k>7. Integers satisfying both are -6,-5,-4,-3,-2,-1,0,1,2, giving 9 values.', NULL, 7, 'medium', 'medium', 180, 'Mixing up the discriminant sign conventions for ''no real roots'' versus ''two distinct real roots''.'),
  ('CAT2022_QA_S3_03', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'ALG_INDICES', 'If (sqrt(7/5))^(3x-y) = 875/2401 and (4a/b)^(6x-y) = (2a/b)^(y-6x), for all non-zero real values of a and b, then the value of x+y is', 'tita', NULL, NULL, NULL, NULL, '14', 'The first equation simplifies to (7/5)^((3x-y)/2) = (7/5)^(-3), giving 3x-y=-6. The second equation forces the exponents to relate so that y=6x since the bases differ. Solving simultaneously gives x=2, y=12, so x+y=14.', NULL, 6, 'medium', 'medium', 180, 'Not spotting that the second equation requires y=6x since the bases (4a/b) and (2a/b) differ.'),
  ('CAT2022_QA_S3_04', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'ALG_LINEAR_WORD', 'Consider six distinct natural numbers such that the average of the two smallest numbers is 14, and the average of the two largest numbers is 28. Then the maximum possible value of the average of these six numbers is', 'mcq', '23', '24', '23.5', '22.5', 'd', 'The two smallest sum to 28 and the two largest sum to 56. To maximise the average, push the two largest as far apart as possible (27 and 29) and the middle two as high as possible (25 and 26). Average = (28+25+26+56)/6 = 22.5.', NULL, 6, 'medium', 'high', 150, 'Trying to maximise the middle two numbers without checking they stay below the two largest and remain distinct.'),
  ('CAT2022_QA_S3_05', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'GEO_TRI_CENTERS', 'Suppose the medians BD and CE of a triangle ABC intersect at a point O. If the area of triangle ABC is 108 sq cm, then the area of triangle EOD, in sq cm, is', 'tita', NULL, NULL, NULL, NULL, '9', 'Area of ABD equals half of ABC, i.e. 54, and area of ADE is half of ABD, i.e. 27. The centroid O divides each median 2:1, so area BEO : EOD = 2:1, giving area EOD = 9.', NULL, 6, 'medium', 'medium', 150, 'Forgetting the 2:1 centroid ratio applies to triangle EOD relative to BEO, not to ABC directly.'),
  ('CAT2022_QA_S3_06', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'ALG_QUAD_ROOT', 'If (3+2sqrt2) is a root of the equation ax^2+bx+c=0 and (4+2sqrt3) is a root of the equation ay^2+my+n=0, where a, b, c, m and n are integers, then the value of (b/m + (c-2b)/n) is', 'mcq', '0', '1', '3', '4', 'd', 'Since coefficients are integers, the conjugate surds (3-2sqrt2) and (4-2sqrt3) are also roots. Sum of first pair = 6 = -b/a, product = 1 = c/a. Sum of second pair = 8 = -m/a, product = 4 = n/a. Substituting gives b/m + (c-2b)/n = 3/4 + 13/4 = 4.', NULL, 7, 'high', 'high', 210, 'Forgetting that integer coefficients force the conjugate surd to also be a root, which is needed to get sum and product of roots.'),
  ('CAT2022_QA_S3_07', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'TW_COMBINED', 'A group of N people worked on a project. They finished 35% of the project by working 7 hours a day for 10 days. Thereafter, 10 people left the group and the remaining people finished the rest of the project in 14 days by working 10 hours a day. Then the value of N is', 'mcq', '150', '23', '36', '140', 'd', 'Total work in man-hours is proportional; N*7*10 equals 35% of total, so total = 200N man-hours, leaving 130N man-hours. (N-10)*14*10 = 130N gives 140N-1400=130N, so 10N=1400, N=140.', NULL, 6, 'medium', 'medium', 210, 'Not converting the 35% figure into an equation for the full project before solving for the remaining work.'),
  ('CAT2022_QA_S3_08', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'MIX_REPLACEMENT', 'A glass contains 500 cc of milk and a cup contains 500 cc of water. From the glass, 150 cc of milk is transferred to the cup and mixed thoroughly. Next, 150 cc of this mixture is transferred from the cup to the glass. Now, the amount of water in the glass and the amount of milk in the cup are in the ratio', 'mcq', '1:1', '10:13', '3:10', '10:3', 'a', 'After the first transfer, the cup has 150 cc milk in 650 cc mixture. Transferring 150 cc of this mixture back moves milk and water in ratio 3:10. Tracking the final volumes shows the water left in the glass and the milk left in the cup both work out to 500*(3/13), giving a 1:1 ratio.', NULL, 5, 'medium', 'medium', 150, 'Losing track of which liquid''s proportion applies to the water side versus the milk side after the second transfer.'),
  ('CAT2022_QA_S3_09', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'SI_BASIC', 'Nitu has an initial capital of Rs 20,000. Out of this, she invests Rs 8,000 at 5.5% in bank A, Rs 5,000 at 5.6% in bank B and the remaining amount at x% in bank C, each rate being simple interest per annum. Her combined annual interest income from these investments is equal to 5% of the initial capital. If she had invested her entire initial capital in bank C alone, then her annual interest income, in rupees, would have been', 'mcq', '700', '800', '900', '1000', 'b', '8000*0.055 + 5000*0.056 + 7000*(x/100) = 0.05*20000, giving 440+280+70x=1000, so x=4%. Investing the full Rs 20,000 at 4% gives 20000*0.04 = Rs 800.', NULL, 6, 'medium', 'low', 180, 'Forgetting the remaining amount invested in bank C is Rs 7,000, not the full Rs 20,000.'),
  ('CAT2022_QA_S3_10', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'TSD_RELATIVE', 'Two cars travel from different locations at constant speeds. To meet each other after starting at the same time, they take 1.5 hours if they travel towards each other, but 10.5 hours if they travel in the same direction. If the speed of the slower car is 60 km/hr, then the distance travelled, in km, by the slower car when it meets the other car while travelling towards each other, is', 'mcq', '100', '90', '120', '150', 'b', 'Both cars take 1.5 hours to meet when moving towards each other, regardless of which car is slower, so the slower car covers 60*1.5=90 km.', NULL, 6, 'low', 'medium', 180, 'Trying to use the same-direction condition unnecessarily, when the answer only needs the towards-each-other meeting time.'),
  ('CAT2022_QA_S3_11', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'MOD_COUNT', 'The arithmetic mean of all the distinct numbers that can be obtained by rearranging the digits in 1421, including itself, is', 'mcq', '2222', '2442', '2592', '3333', 'a', 'There are 4!/2!=12 distinct 4-digit arrangements of 1,1,2,4. Each place value gets a fixed proportion of 1s, 2s and 4s across the 12 numbers, giving a digit-sum contribution of 24 per place, so total sum = 24*1111. Mean = 24*1111/12 = 2222.', NULL, 6, 'medium', 'medium', 150, 'Not accounting for the repeated digit 1 when counting how many times each digit appears in each place value.'),
  ('CAT2022_QA_S3_12', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'GEO_MENS_2D', 'The lengths of all four sides of a quadrilateral are integer valued. If three of its sides are of length 1 cm, 2 cm and 4 cm, then the total number of possible lengths of the fourth side is', 'mcq', '3', '4', '6', '5', 'd', 'For a quadrilateral, any side must be less than the sum of the other three: d<1+2+4=7, and greater than the difference-based bound d>4-1-2=1. So d can be 2,3,4,5,6, giving 5 integer values.', NULL, 5, 'low', 'medium', 150, 'Applying the triangle-inequality bound instead of the quadrilateral-side bound, or missing one of the two inequality directions.'),
  ('CAT2022_QA_S3_13', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'ALG_AP', 'The average of all 3-digit terms in the arithmetic progression 38, 55, 72, ..., is', 'tita', NULL, NULL, NULL, NULL, '548', 'The general term is 17k+4. The smallest 3-digit term in this form is 106 (k=6) and the largest is 990 (k=58), giving an AP of 3-digit terms with first term 106 and last term 990. Average = (106+990)/2 = 548.', NULL, 6, 'medium', 'medium', 180, 'Miscounting the number of 3-digit terms, though the average of an AP only needs the first and last term regardless of count.'),
  ('CAT2022_QA_S3_14', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'ALG_LINEAR_WORD', 'In an examination, the average marks of students in sections A and B are 32 and 60, respectively. The number of students in section A is 10 less than that in section B. If the average marks of all the students across both the sections combined is an integer, then the difference between the maximum and minimum possible number of students in section A is', 'tita', NULL, NULL, NULL, NULL, '63', 'With a students in A and a+10 in B, the combined average is 46 + 70/(a+5), which must be an integer, so (a+5) must divide 70. Valid values of a are 2,5,9,30,65, giving a maximum-minimum difference of 65-2=63.', NULL, 6, 'high', 'high', 210, 'Not simplifying the combined average expression fully before searching for divisors, leading to a much harder search.'),
  ('CAT2022_QA_S3_15', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'ALG_FUNC_COMP', 'Let r be a real number and f(x) = 2x-r if x>=r, and f(x)=r if x<r. Then the equation f(x)=f(f(x)) holds for all real values of x where', 'mcq', 'x > r', 'x <= r', 'x != r', 'x >= r', 'b', 'For x<r, f(x)=r and f(f(x))=f(r)=2r-r=r, so the equation holds automatically. For x>=r, f(x)=2x-r and f(f(x))=4x-3r, and setting these equal forces x=r, a single point in that region. So the equation holds for all x<=r.', NULL, 7, 'medium', 'high', 210, 'Assuming the equation holds for x>=r generally instead of checking it only holds at the single boundary point x=r within that region.'),
  ('CAT2022_QA_S3_16', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'GEO_SECTOR', 'In a triangle ABC, AB=AC=8 cm. A circle drawn with BC as diameter passes through A. Another circle drawn with center at A passes through B and C. Then the area, in sq cm, of the overlapping region between the two circles is', 'mcq', '16*pi', '16(pi-1)', '32(pi-1)', '32*pi', 'c', 'Since BC is a diameter of the first circle and A lies on it, angle BAC=90 degrees, so BC=8sqrt2 and the first circle has radius 4sqrt2, area 32pi. The second circle has radius AB=8. The overlap equals half the first circle''s area plus the minor sector of the second circle minus triangle ABC: 16pi + (16pi-32) = 32(pi-1).', NULL, 7, 'high', 'high', 240, 'Not recognising angle BAC=90 degrees from BC being the diameter, which is the key step to finding the first circle''s radius.'),
  ('CAT2022_QA_S3_17', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'NS_SUCCESSIVE_DIV', 'A school has less than 5000 students and if the students are divided equally into teams of either 9 or 10 or 12 or 25 each, exactly 4 are always left out. However, if they are divided into teams of 11 each, no one is left out. The maximum number of teams of 12 each that can be formed out of the students in the school is', 'tita', NULL, NULL, NULL, NULL, '150', 'The student count is of the form LCM(9,10,12,25)k+4 = 900k+4, and under 5000 this gives k=1,2,3,4,5. Checking divisibility by 11 leaves only k=2, i.e. 1804 students. Teams of 12: 1800/12 = 150.', NULL, 7, 'medium', 'medium', 210, 'Forgetting to also check the divisible-by-11 condition, or miscomputing the LCM of 9, 10, 12, 25.'),
  ('CAT2022_QA_S3_18', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'ALG_FUNC_OPT', 'The minimum possible value of (x^2-6x+10)/(3-x), for x<3, is', 'mcq', '-1/2', '2', '1/2', '-2', 'b', 'Substitute y=3-x>0, so the expression becomes ((3-y)^2-6(3-y)+10)/y = (y^2+1)/y = y+1/y. By AM-GM this is minimised at y=1, giving minimum value 2.', NULL, 6, 'medium', 'medium', 180, 'Forgetting to check that y=3-x is positive before applying AM-GM to y+1/y.'),
  ('CAT2022_QA_S3_19', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'ALG_LINEAR_WORD', 'A donation box can receive only cheques of Rs 100, Rs 250, and Rs 500. On one good day, the donation box was found to contain exactly 100 cheques amounting to a total sum of Rs 15250. Then, the maximum possible number of cheques of Rs 500 that the donation box may have contained, is', 'tita', NULL, NULL, NULL, NULL, '12', 'Let x, y, z be the counts of Rs 100, Rs 250, Rs 500 cheques. x+y+z=100 and 2x+5y+10z=305. Subtracting twice the first from the second gives 3y+8z=105, so z is maximised when y is minimised. At z=12, y=3, x=85, all non-negative, giving the maximum z=12.', NULL, 6, 'medium', 'medium', 180, 'Not checking that the resulting x stays non-negative when maximising z.'),
  ('CAT2022_QA_S3_20', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'TSD_ESCALATOR', 'Moody takes 30 seconds to finish riding an escalator if he walks on it at his normal speed in the same direction. He takes 20 seconds to finish riding the escalator if he walks at twice his normal speed in the same direction. If Moody decides to stand still on the escalator, then the time, in seconds, needed to finish riding the escalator is', 'tita', NULL, NULL, NULL, NULL, '60', 'Let Moody''s normal step rate be x steps/sec and the escalator''s rate be y steps/sec. Total steps = 30(x+y) = 20(2x+y), giving x=y. Total steps = 60y, so standing still takes 60y/y = 60 seconds.', NULL, 5, 'medium', 'medium', 150, 'Treating the escalator''s total step count as unknown and unrelated between the two scenarios instead of equating them.'),
  ('CAT2022_QA_S3_21', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'TSD_RELATIVE', 'Two ships are approaching a port along straight routes at constant speeds. Initially, the two ships and the port formed an equilateral triangle with sides of length 24 km. When the slower ship travelled 8 km, the triangle formed by the new positions of the two ships and the port became right-angled. When the faster ship reaches the port, the distance, in km, between the other ship and the port will be', 'mcq', '4', '12', '8', '6', 'b', 'After the slower ship travels 8 km, its remaining distance to port is 16 km, and the angle at the port stays 60 degrees. The right angle forms at the faster ship''s new position, giving cos60=OF/16, so OF=8. This means while the slower ship covered 8 km, the faster ship covered 24-8=16 km, a 1:2 speed ratio. So when the faster ship covers all 24 km, the slower ship covers 12 km, leaving 24-12=12 km to the port.', NULL, 7, 'high', 'high', 210, 'Misidentifying which vertex holds the right angle, which flips which distance the cosine rule should be applied to.'),
  ('CAT2022_QA_S3_22', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'TW_COMBINED', 'Bob can finish a job in 40 days, if he works alone. Alex is twice as fast as Bob and thrice as fast as Cole in the same job. Suppose Alex and Bob work together on the first day, Bob and Cole work together on the second day, Cole and Alex work together on the third day, and then they continue the work by repeating this three-day roster, with Alex and Bob working together on the fourth day, and so on. Then the total number of days Alex would have worked when the job gets finished, is', 'tita', NULL, NULL, NULL, NULL, '11', 'Taking total work as 120 units, Bob=3, Alex=6, Cole=2 units/day. Each 3-day cycle (Alex+Bob, Bob+Cole, Cole+Alex) completes 9+5+8=22 units. After 5 cycles (15 days) 110 units are done, and the job finishes on day 17 (an Alex+Bob day). Alex works 2 of every 3 days, so across days 1-15 he works 10 days, plus day 16 and day 17, giving 11 total working days for Alex.', NULL, 7, 'high', 'high', 210, 'Losing track of which day-type falls where in the roster once past the initial full cycles, causing an off-by-one in Alex''s total working days.'),
  ('CAT2022_QA_S2_01', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'SI_BASIC', 'Mr. Pinto invests one-fifth of his capital at 6%, one-third at 10% and the remaining at 1%, each rate being simple interest per annum. Then, the minimum number of years required for the cumulative interest income from these investments to equal or exceed his initial capital is', 'tita', NULL, NULL, NULL, NULL, '20', 'With capital 15x split as 3x, 5x, 7x across the three rates, total interest per year = (3x*6+5x*10+7x*1)/100 = 0.75x. For cumulative interest over T years to reach 15x, 0.75xT>=15x, giving T>=20.', NULL, 6, 'low', 'medium', 150, 'Splitting the capital in the wrong proportion (1/5, 1/3, and the remainder) when converting fractions to a common multiple.'),
  ('CAT2022_QA_S2_02', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'ALG_LINEAR_WORD', 'The average of a non-decreasing sequence of N numbers a1, a2, ..., aN is 300. If a1 is replaced by 6a1, the new average becomes 400. Then, the number of possible values of a1, is', 'tita', NULL, NULL, NULL, NULL, '14', 'The sum increases by 5a1 to raise the average by 100, so 5a1=100N, giving a1=20N. Since the sequence is non-decreasing with average 300, a1 must be at most 300 and N cannot be 1, so N ranges from 2 to 15, giving 14 possible values.', NULL, 6, 'medium', 'high', 150, 'Including N=1 as a valid case, or not bounding a1<=300 which restricts the range of N.'),
  ('CAT2022_QA_S2_03', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'ALG_EXP', 'The number of integer solutions of the equation (x^2-10)^(x^2-3x-10) = 1 is', 'tita', NULL, NULL, NULL, NULL, '4', 'This holds in three cases: exponent zero with nonzero base (x^2-3x-10=0 giving x=5,-2, both valid); base equal to 1 (x^2=11, no integer solution); or base equal to -1 with an even exponent (x^2=9 giving x=3,-3, and checking the exponent is even in both cases confirms validity). Total: 4 integer solutions.', NULL, 6, 'medium', 'high', 180, 'Missing the base=-1-with-even-exponent case, which is easy to overlook in equations of the form a^b=1.'),
  ('CAT2022_QA_S2_04', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'ALG_LINEAR_WORD', 'Manu earns Rs 4000 per month and wants to save an average of Rs 550 per month in a year. In the first nine months, his monthly expense was Rs 3500, and he foresees that, tenth month onward, his monthly expense will increase to Rs 3700. In order to meet his yearly savings target, his monthly earnings, in rupees, from the tenth month onward should be', 'mcq', '4400', '4200', '4300', '4350', 'a', 'Yearly savings target = 550*12 = Rs 6600. Savings in the first 9 months = 9*(4000-3500) = Rs 4500, leaving Rs 2100 to save over the last 3 months, i.e. Rs 700/month. With expenses of Rs 3700, earnings should be 3700+700 = Rs 4400.', NULL, 5, 'low', 'low', 150, 'Applying the required average savings per month directly to the last three months rather than solving for the remaining shortfall first.'),
  ('CAT2022_QA_S2_05', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'GEO_TRIG_RATIO', 'In triangle ABC, altitudes AD and BE are drawn to the corresponding bases. If angle BAC=45 degrees and angle ABC=theta, then AD/BE equals', 'mcq', 'sqrt2 * cos(theta)', '(sin(theta)+cos(theta))/sqrt2', '1', 'sqrt2 * sin(theta)', 'd', 'Since angle BAE=45 degrees, triangle ABE is right-isosceles with AE=BE=x and AB=x*sqrt2. In right triangle ABD, sin(theta)=AD/AB=AD/(x*sqrt2), so AD=x*sqrt2*sin(theta), giving AD/BE = sqrt2*sin(theta).', NULL, 6, 'medium', 'medium', 180, 'Not spotting that angle BAE=45 degrees makes triangle ABE isosceles right-angled, which is the key relation linking AB to BE.'),
  ('CAT2022_QA_S2_06', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'ALG_QUAD_ROOT', 'Let f(x) be a quadratic polynomial in x such that f(x)>=0 for all real numbers x. If f(2)=0 and f(4)=6, then f(-2) is equal to', 'mcq', '12', '24', '6', '36', 'b', 'f(x)>=0 everywhere with f(2)=0 means x=2 is a repeated root, so f(x)=a(x-2)^2 for some a>0. f(4)=6 gives 4a=6, so a=3/2. Then f(-2)=1.5*16=24.', NULL, 6, 'medium', 'medium', 180, 'Not recognising that f(x)>=0 with a zero at x=2 forces x=2 to be a double root.'),
  ('CAT2022_QA_S2_07', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'ALG_HIGHER_DEGREE', 'Let r and c be real numbers. If r and -r are roots of 5x^3+cx^2-10x+9=0, then c equals', 'mcq', '-9/2', '9/2', '-4', '4', 'a', 'Let the third root be p. Sum of roots: r-r+p=-c/5, so p=-c/5. Sum of pairwise products: -r^2+pr-pr=-2, so r^2=2. Product of roots: -r^2*p=-9/5, so p=9/10. Substituting into p=-c/5 gives c=-9/2.', NULL, 7, 'medium', 'high', 210, 'Sign errors when writing Vieta''s formulas for a cubic, especially the pairwise-product sum.'),
  ('CAT2022_QA_S2_08', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'TSD_RELATIVE', 'Two ships meet mid-ocean, and then, one ship goes south and the other ship goes west, both travelling at constant speeds. Two hours later, they are 60 km apart. If the speed of one of the ships is 6 km per hour more than the other one, then the speed, in km per hour, of the slower ship is', 'mcq', '20', '12', '18', '24', 'c', 'In 2 hours, the ships cover 2x and 2(x+6) km along perpendicular directions. By Pythagoras, (2x)^2+(2x+12)^2=60^2, simplifying to x^2+6x-432=0, giving x=18.', NULL, 6, 'medium', 'medium', 180, 'Forgetting the two directions are perpendicular, so Pythagoras applies rather than simple addition of distances.'),
  ('CAT2022_QA_S2_09', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'ALG_FUNC_COMP', 'Suppose for all integers x, there are two functions f and g such that f(x)+f(x-1)-1=0 and g(x)=x^2. If f(x^2-x)=5, then the value of the sum f(g(5))+g(f(5)) is', 'tita', NULL, NULL, NULL, NULL, '12', 'Setting x=1 in the recurrence and the given condition gives f(0)=5, then f(1)+f(0)=1 gives f(1)=-4, f(2)+f(1)=1 gives f(2)=5. So f(n)=5 for even n and -4 for odd n. f(g(5))+g(f(5)) = f(25)+g(-4) = -4+16 = 12.', NULL, 7, 'medium', 'high', 210, 'Not identifying the alternating even/odd pattern in f(n) before evaluating f(25) and f(5).'),
  ('CAT2022_QA_S2_10', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'ALG_LINEAR_WORD', 'In an examination, there were 75 questions. 3 marks were awarded for each correct answer, 1 mark was deducted for each wrong answer and 1 mark was awarded for each unattempted question. Rayan scored a total of 97 marks in the examination. If the number of unattempted questions was higher than the number of attempted questions, then the maximum number of correct answers that Rayan could have given in the examination is', 'tita', NULL, NULL, NULL, NULL, '24', 'With x correct, y wrong, z unattempted: x+y+z=75 and 3x-y+z=97. Adding gives 2x+z=86, subtracting gives x-y=11. The unattempted condition z>x+y=75-z gives z>37.5, so minimum z=38, giving 2x=48, x=24.', NULL, 7, 'medium', 'high', 210, 'Not translating ''unattempted greater than attempted'' into z>75-z before solving for the minimum z.'),
  ('CAT2022_QA_S2_11', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'GEO_POLY', 'Regular polygons A and B have number of sides in the ratio 1:2 and interior angles in the ratio 3:4. Then the number of sides of B equals', 'tita', NULL, NULL, NULL, NULL, '10', 'Let A have n sides and B have 2n sides. Interior angle ratio: [(n-2)*180/n] / [(2n-2)*180/(2n)] = 3/4, which simplifies to (n-2)/(n-1)=3/4, giving n=5. So B has 2n=10 sides.', NULL, 6, 'medium', 'medium', 150, 'Errors simplifying the interior angle formula fractions before cross-multiplying.'),
  ('CAT2022_QA_S2_12', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'RATIO_BASIC', 'In an election, there were four candidates and 80% of the registered voters casted their votes. One of the candidates received 30% of the casted votes while the other three candidates received the remaining casted votes in the proportion 1:2:3. If the winner of the election received 2512 votes more than the candidate with the second highest votes, then the number of registered voters was', 'mcq', '50240', '40192', '60288', '62800', 'd', 'With 100x registered voters, cast votes=80x, one candidate gets 24x, and the rest 56x split 1:2:3 giving the top of that group 28x. The winner (28x) exceeds the runner-up (24x) by 4x=2512, so x=628, giving registered voters = 62800.', NULL, 6, 'high', 'high', 210, 'Not checking which of the four candidates is actually the winner and which is the runner-up before setting up the difference equation.'),
  ('CAT2022_QA_S2_13', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'ALG_RECURRENCE', 'On day one, there are 100 particles in a laboratory experiment. On day n, where n>=2, one out of every n particles produces another particle. If the total number of particles in the laboratory experiment increases to 1000 on day m, then m equals', 'mcq', '19', '16', '18', '17', 'a', 'On day 2, 100/2 = 50 particles are added, giving 150. On day 3, 150/3 = 50 are added, giving 200. The count on day n is always 50n, so the number added each day, (50n)/n, stays fixed at 50. The totals form an AP: 100 + 50(m − 1) = 1000 ⇒ m − 1 = 18 ⇒ m = 19.', NULL, 7, 'medium', 'medium', 180, 'Not noticing that the addition stays fixed at 50 particles per day, and instead trying to recompute the fraction each day.'),
  ('CAT2022_QA_S2_14', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'MOD_COUNT', 'The number of integers greater than 2000 that can be formed with the digits 0, 1, 2, 3, 4, 5, using each digit at most once, is', 'mcq', '1440', '1200', '1480', '1420', 'a', '4-digit numbers >2000: first digit from {2,3,4,5} (4 ways), remaining 3 digits from the other 5 in order (5*4*3=60 ways), giving 240. 5-digit numbers: first digit nonzero (5 ways), then 5*4*3*2 for the rest = 600. 6-digit numbers: similarly 600. Total = 240+600+600 = 1440.', NULL, 6, 'medium', 'medium', 210, 'Forgetting all 5-digit and 6-digit numbers automatically exceed 2000, so no restriction beyond the leading digit being nonzero is needed for those cases.'),
  ('CAT2022_QA_S2_15', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'NS_FACTORIAL', 'For some natural number n, assume that (15,000)! is divisible by (n!)!. The largest possible value of n is', 'mcq', '4', '7', '6', '5', 'b', '(15000)! is divisible by (n!)! whenever n!<=15000. Since 7!=5040<=15000 but 8!=40320>15000, the largest valid n is 7.', NULL, 6, 'low', 'medium', 150, 'Confusing n! with n when checking the bound, or stopping the factorial check one step too early.'),
  ('CAT2022_QA_S2_16', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'TW_COMBINED', 'Working alone, the times taken by Anu, Tanu and Manu to complete any job are in the ratio 5:8:10. They accept a job which they can finish in 4 days if they all work together for 8 hours per day. However, Anu and Tanu work together for the first 6 days, working 6 hours 40 minutes per day. Then, the number of hours that Manu will take to complete the remaining job working alone is', 'tita', NULL, NULL, NULL, NULL, '6', 'With rates in the ratio 8:5:4 (inverse of times), the job finishes in 32 hours (4 days x 8 hrs) at combined rate 17, giving total work = 544 units. Anu and Tanu work 40 hours (6 days x 6h40m) at combined rate 13, completing 520 units, leaving 24 units, which Manu (rate 4) finishes in 6 hours.', NULL, 7, 'high', 'high', 210, 'Mixing up which ratio value corresponds to which worker''s rate versus time, since rate is inverse of time taken alone.'),
  ('CAT2022_QA_S2_17', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'MIX_REPLACEMENT', 'There are two containers of the same volume, first container half-filled with sugar syrup and the second container half-filled with milk. Half the content of the first container is transferred to the second container, and then half of this mixture is transferred back to the first container. Next, half the content of the first container is transferred back to the second container. Then the ratio of sugar syrup and milk in the second container is', 'mcq', '4:5', '6:5', '5:4', '5:6', 'd', 'Tracking volumes through each transfer (using 100L half-fills as a base), after all three steps the second container holds 62.5L syrup and 75L milk, giving a ratio of 62.5:75 = 5:6.', NULL, 6, 'medium', 'high', 210, 'Losing track of the syrup and milk quantities separately across three successive transfers instead of tabulating each step.'),
  ('CAT2022_QA_S2_18', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'ALG_AP', 'Consider the arithmetic progression 3, 7, 11, ... and let An denote the sum of the first n terms of this progression. Then the value of (1/25)*sum(n=1 to 25) An is', 'mcq', '455', '442', '415', '404', 'a', 'An = n(2n+1), so summing gives 2*sum(n^2) + sum(n) using standard sum formulas. Substituting n=25 into the resulting expression and dividing by 25 gives 26(17)+13 = 455.', NULL, 6, 'medium', 'medium', 180, 'Using the wrong closed-form sum for An before summing over n, since An itself is already a sum expression.'),
  ('CAT2022_QA_S2_19', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'ALG_LOG_EQ', 'The number of distinct integer values of n satisfying (4-log2(n))/(3-log4(n)) < 0, is', 'tita', NULL, NULL, NULL, NULL, '47', 'Let y=log2(n). Since log4(n)=y/2, the inequality becomes (4-y)/(3-y/2)<0, which simplifies to (4-y)(6-y)<0, i.e. 4<y<6, so 16<n<64. This gives integers 17 through 63, which is 47 values.', NULL, 7, 'medium', 'medium', 180, 'Not converting log4(n) to base 2 correctly before combining the two log terms into a single inequality.'),
  ('CAT2022_QA_S2_20', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'ALG_INEQ_LINEAR', 'If a and b are non-negative real numbers such that a+2b=6, then the average of the maximum and minimum possible values of (a+b) is', 'mcq', '3', '4', '3.5', '4.5', 'd', 'a+b = 6-b, so it''s maximised when b is minimum (b=0, giving 6) and minimised when b is maximum (b=3, since a>=0 caps b at 3, giving 3). Average of 6 and 3 is 4.5.', NULL, 6, 'low', 'medium', 150, 'Not using the non-negativity of a to bound the maximum value of b.'),
  ('CAT2022_QA_S2_21', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'ALG_LINEAR_WORD', 'Five students, including Amit, appear for an examination in which possible marks are integers between 0 and 50, both inclusive. The average marks for all the students is 38 and exactly three students got more than 32. If no two students got the same marks and Amit got the least marks among the five students, then the difference between the highest and lowest possible marks of Amit is', 'mcq', '22', '21', '24', '20', 'd', 'Total marks = 190. To minimise Amit''s marks, maximise the other four: the three above 32 take the highest distinct values 50,49,48, and the fourth (at most 32) takes 32, giving Amit''s minimum as 190-179=11. To maximise Amit''s marks while still being the lowest, Amit can be at most 31. Difference = 31-11 = 20.', NULL, 7, 'high', 'high', 210, 'Forgetting that exactly one of the four non-Amit students must be at most 32 (not above it), which constrains both the minimum and maximum bounds for Amit.'),
  ('CAT2022_QA_S2_22', 2022, 'Slot 2', 'CAT 2022 Slot 2', TRUE, 'GEO_TRI_SPECIAL', 'The length of each side of an equilateral triangle ABC is 3 cm. Let D be a point on BC such that the area of triangle ADC is half the area of triangle ABD. Then the length of AD, in cm, is', 'mcq', 'sqrt8', 'sqrt6', 'sqrt7', 'sqrt5', 'c', 'The area ratio gives BD:DC = 2:1, so BD=2, DC=1. Applying the cosine rule in triangle ADC with angle ACD=60 degrees: AD^2 = AC^2+CD^2-2(AC)(CD)cos60 = 9+1-3 = 7, giving AD=sqrt7.', NULL, 7, 'medium', 'high', 210, 'Applying the cosine rule with the wrong angle (using angle ADC or ABD instead of the known 60-degree angle ACB).'),
  ('CAT2022_QA_S1_01', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'RATIO_BASIC', 'In a village, the ratio of number of males to females is 5:4. The ratio of number of literate males to literate females is 2:3. The ratio of the number of illiterate males to illiterate females is 4:3. If 3600 males in the village are literate, then the total number of females in the village is', 'tita', NULL, NULL, NULL, NULL, '43200', 'Literate males=3600 gives literate females=5400 (from 2:3 ratio). With males=5y, females=4y, illiterate males=5y-3600 and illiterate females=4y-5400 in ratio 4:3 gives 15y-10800=16y-21600, so y=10800. Total females=4y=43200.', NULL, 6, 'medium', 'medium', 180, 'Mixing up which ratio (literate or illiterate) applies to which equation when setting up the cross-multiplication.'),
  ('CAT2022_QA_S1_02', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'ALG_LINEAR_WORD', 'The average weight of students in a class increases by 600 gm when some new students join the class. If the average weight of the new students is 3 kg more than the average weight of the original students, then the ratio of the number of original students to the number of new students is', 'mcq', '1:4', '1:2', '4:1', '3:1', 'c', 'With n original students (average x) and m new students (average x+3), the combined average satisfies (nx+m(x+3))/(n+m)=x+0.6, which simplifies to 2.4m=0.6n, so n:m=4:1.', NULL, 6, 'medium', 'medium', 150, 'Setting up the weighted average equation with the wrong sign or forgetting to cancel the common x term correctly.'),
  ('CAT2022_QA_S1_03', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'ALG_AP', 'For any natural number n, suppose the sum of the first n terms of an arithmetic progression is (n+2n^2). If the nth term of the progression is divisible by 9, then the smallest possible value of n is', 'mcq', '9', '4', '7', '8', 'c', 'Tn = Sn − S(n−1) = (n + 2n²) − [(n−1) + 2(n−1)²] = 4n − 1. For 9 | (4n − 1) we need 4n ≡ 1 (mod 9); since 4 × 7 = 28 ≡ 1 (mod 9), the solutions are n ≡ 7 (mod 9). The smallest positive value is n = 7, giving T7 = 27.', NULL, 7, 'medium', 'medium', 180, 'Computing Sn-1 incorrectly by not expanding 2(n-1)^2 fully before subtracting.'),
  ('CAT2022_QA_S1_04', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'ALG_FUNC_OPT', 'Let 0<=a<=x<=100 and f(x) = |x-a| + |x-100| + |x-a-50|. Then the maximum value of f(x) becomes 100 when a is equal to', 'mcq', '25', '100', '50', '0', 'c', 'For a<=x<=100, |x-a|=x-a and |x-100|=100-x, so f(x)=100+|x-a-50|. This is maximised at the endpoints x=a or x=100, where |x-a-50| equals a in both cases only when a=50, giving f(x)max=100.', NULL, 6, 'medium', 'high', 180, 'Not carefully checking both endpoints (x=a and x=100) to see which gives the true maximum of |x-a-50| within the allowed range.'),
  ('CAT2022_QA_S1_05', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'TSD_TRAIN', 'Trains A and B start travelling at the same time towards each other with constant speeds from stations X and Y, respectively. Train A reaches station Y in 10 minutes while train B takes 9 minutes to reach station X after meeting train A. Then the total time taken, in minutes, by train B to travel from station Y to station X is', 'mcq', '6', '15', '10', '12', 'b', 'Using D/a=10 and the post-meeting time for B of 9 minutes, along with the standard meeting-point relation between the two trains'' speeds, solving the resulting equations gives D/b=15, so train B takes 15 minutes for the full journey.', NULL, 6, 'high', 'high', 180, 'Confusing the meeting-point distances covered by each train before setting up the ratio equations.'),
  ('CAT2022_QA_S1_06', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'GEO_TRAP', 'A trapezium ABCD has side AD parallel to BC, angle BAD=90 degrees, BC=3 cm and AD=8 cm. If the perimeter of this trapezium is 36 cm, then its area, in sq cm, is', 'tita', NULL, NULL, NULL, NULL, '66', 'Drop a perpendicular from C to AD, creating a right triangle with legs (AD-BC)=5 and height y, and hypotenuse CD=sqrt(y^2+25). The perimeter equation 11+y+sqrt(y^2+25)=36 solves to y=12. Area = (1/2)(AD+BC)*height = (1/2)(11)(12) = 66.', NULL, 6, 'medium', 'medium', 180, 'Setting up the perimeter equation without isolating the square root term before squaring, leading to algebra errors.'),
  ('CAT2022_QA_S1_07', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'PL_CP_SP', 'Ankita buys 4 kg cashews, 14 kg peanuts and 6 kg almonds when the cost of 7 kg cashews is the same as that of 30 kg peanuts or 9 kg almonds. She mixes all the three nuts and marks a price for the mixture in order to make a profit of Rs 1752. She sells 4 kg of the mixture at this marked price and the remaining at a 20% discount on the marked price, thus making a total profit of Rs 744. Then the amount, in rupees, that she had spent in buying almonds is', 'mcq', '1680', '1176', '2520', '1440', 'a', 'With 7C=30P=9A=630k, prices are C=90k, P=21k, A=70k, so cost of the mixture = 4(90k)+14(21k)+6(70k)=1074k. Using the profit equations from the full-price and discounted sales, solving gives k=4, so cost of almonds = 6*70*4 = Rs 1680.', NULL, 6, 'high', 'high', 210, 'Not converting all three nut costs to a common multiple (630k) before setting up the total cost-price expression.'),
  ('CAT2022_QA_S1_08', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'NS_HCF', 'Let A be the largest positive integer that divides all the numbers of the form 3^k+4^k+5^k, and B be the largest positive integer that divides all the numbers of the form 4^k+3(4^k)+4^(k+2), where k is any positive integer. Then (A+B) equals', 'tita', NULL, NULL, NULL, NULL, '82', 'For A, testing k=1 (12), k=2 (50), k=3 (216) shows their HCF is 2, so A=2. For B, the expression simplifies to 4^k(1+3+16)=20*4^k=5*4^(k+1), and the constant factor extractable for every k is 80, so B=80. A+B=82.', NULL, 6, 'medium', 'medium', 180, 'Not fully simplifying 4^(k+2) as 16*4^k before combining terms algebraically.'),
  ('CAT2022_QA_S1_09', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'ALG_INEQ_QUAD', 'Let a, b, c be non-zero real numbers such that b^2<4ac, and f(x)=ax^2+bx+c. If the set S consists of all integers m such that f(m)<0, then the set S must necessarily be', 'mcq', 'the set of all positive integers', 'the set of all integers', 'either the empty set or the set of all integers', 'the empty set', 'c', 'Since b^2<4ac, the discriminant is negative, so f(x) never crosses zero and keeps one sign for all real x, positive everywhere if a>0 and negative everywhere if a<0. So S is either empty (if a>0) or all integers (if a<0).', NULL, 6, 'low', 'medium', 180, 'Not considering both possible signs of the leading coefficient a before concluding what S must be.'),
  ('CAT2022_QA_S1_10', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'MOD_DISTRIBUTION', 'The number of ways of distributing 20 identical balloons among 4 children such that each child gets some balloons but no child gets an odd number of balloons, is', 'tita', NULL, NULL, NULL, NULL, '84', 'Writing each child''s count as 2a,2b,2c,2d with a,b,c,d>=1, we need a+b+c+d=10 with each variable at least 1. The number of positive integer solutions is C(9,3)=84.', NULL, 6, 'medium', 'medium', 150, 'Forgetting to halve the balloon counts before applying the stars-and-bars formula, or using C(10,3) instead of C(9,3).'),
  ('CAT2022_QA_S1_11', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'ALG_SPECIAL', 'Let a and b be natural numbers. If a^2+ab+a=14 and b^2+ab+b=28, then (2a+b) equals', 'mcq', '8', '7', '10', '9', 'a', 'Dividing the two equations gives a/b=1/2, so b=2a. Substituting into the first equation gives a(3a+1)=14, i.e. 3a^2+a-14=0, which factors to (a-2)(3a+7)=0, giving a=2, b=4. So 2a+b=2(2)+4=8.', NULL, 6, 'medium', 'medium', 180, 'Taking the ratio of the two equations without verifying that the common factor (a+b+1) is indeed the same in both.'),
  ('CAT2022_QA_S1_12', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'PL_CP_SP', 'Amal buys 110 kg of syrup and 120 kg of juice, syrup being 20% less costly than juice, per kg. He sells 10 kg of syrup at 10% profit and 20 kg of juice at 20% profit. Mixing the remaining juice and syrup, Amal sells the mixture at Rs 308.32 per kg and makes an overall profit of 64%. Then, Amal''s cost price for syrup, in rupees per kg, is', 'tita', NULL, NULL, NULL, NULL, '160', 'With juice CP=10CP and syrup CP=8CP per kg, total cost = 880CP+1200CP=2080CP. Selling price = 88CP (from 10kg syrup) + 240CP (from 20kg juice) + 308.32*200 for the remaining 200kg mixture. Setting total SP=1.64*2080CP and solving gives CP=20, so syrup''s cost price = 8*20 = Rs 160.', NULL, 7, 'high', 'high', 210, 'Forgetting to account separately for the selling price of the initially-sold 10kg syrup and 20kg juice before adding the mixture''s selling price.'),
  ('CAT2022_QA_S1_13', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'GEO_CYCLIC', 'All the vertices of a rectangle lie on a circle of radius R. If the perimeter of the rectangle is P, then the area of the rectangle is', 'mcq', 'P^2/16 - R^2', 'P^2/8 - 2R^2', 'P^2/2 - 2PR', 'P^2/8 - R^2/2', 'b', 'For sides l and b, l^2+b^2=(2R)^2=4R^2 (diagonal=diameter) and P=2(l+b), so P/2=l+b. Squaring: P^2/4=l^2+b^2+2lb=4R^2+2lb, giving lb=P^2/8-2R^2.', NULL, 6, 'medium', 'medium', 180, 'Forgetting that the diagonal of a rectangle inscribed in a circle equals the circle''s diameter (2R, not R).'),
  ('CAT2022_QA_S1_14', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'ALG_LINEAR_WORD', 'The average of three integers is 13. When a natural number n is included, the average of these four integers remains an odd integer. The minimum possible value of n is', 'mcq', '3', '4', '5', '1', 'c', 'Sum of three integers = 39. The new average (39+n)/4 must be an odd integer. Testing small natural numbers, n=5 gives 44/4=11, which is odd, and it''s the smallest n for which this works.', NULL, 6, 'low', 'medium', 150, 'Not checking that the resulting average is specifically odd (not just an integer), which rules out smaller n values like 1.'),
  ('CAT2022_QA_S1_15', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'MIX_ALLIGATION', 'A mixture contains lemon juice and sugar syrup in equal proportion. If a new mixture is created by adding this mixture and sugar syrup in the ratio 1:3, then the ratio of lemon juice and sugar syrup in the new mixture is', 'mcq', '1:4', '1:5', '1:6', '1:7', 'd', 'In the original mixture, lemon juice is 50% and sugar syrup 50%. Mixing 1 part of this with 3 parts pure sugar syrup: lemon juice = 1*50=50 units, sugar syrup = 1*50+3*100=350 units, giving a ratio of 50:350=1:7.', NULL, 6, 'low', 'medium', 150, 'Forgetting to include the sugar-syrup contribution from the original 1:1 mixture itself when adding the additional 3 parts.'),
  ('CAT2022_QA_S1_16', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'ALG_INEQ_MOD', 'The largest real value of a for which the equation |x+a| + |x-1| = 2 has an infinite number of solutions for x is', 'mcq', '-1', '0', '1', '2', 'c', 'Infinite solutions occur when the two absolute-value terms fully cancel over an interval, which happens either when a=-3 (from one sign case) or a=1 (from the other). The largest such value of a is 1.', NULL, 6, 'medium', 'high', 180, 'Only checking one of the two boundary cases for where the modulus terms can cancel over an interval.'),
  ('CAT2022_QA_S1_17', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'SET_VENN', 'In a class of 100 students, 73 like coffee, 80 like tea and 52 like lemonade. It may be possible that some students do not like any of these three drinks. Then the difference between the maximum and minimum possible number of students who like all the three drinks is', 'mcq', '47', '53', '52', '48', 'a', 'Let n, s, d, t be counts liking none, exactly one, exactly two, and all three drinks. n+s+d+t=100 and s+2d+3t=205. Subtracting gives d+2t-n=105. Maximum t is 52 (d=1, n=0); minimum t is 5 (d=95, n=0). Difference = 52-5 = 47.', NULL, 6, 'high', 'high', 180, 'Not verifying the minimum-t scenario still satisfies the total-students equation alongside the sum-of-likes equation.'),
  ('CAT2022_QA_S1_18', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'GEO_QUAD', 'Let ABCD be a parallelogram such that the coordinates of its three vertices A, B, C are (1, 1), (3, 4) and (-2, 8), respectively. Then, the coordinates of the vertex D are', 'mcq', '(0, 11)', '(4, 5)', '(-3, 4)', '(-4, 5)', 'd', 'In a parallelogram, the diagonals bisect each other, so the midpoint of AC equals the midpoint of BD. Midpoint of AC = (-0.5, 4.5). Setting this equal to the midpoint of B(3,4) and D(x,y) gives x=-4, y=5.', NULL, 6, 'low', 'medium', 150, 'Using the wrong pair of opposite vertices (e.g. AB instead of AC) when applying the diagonal-bisection property.'),
  ('CAT2022_QA_S1_19', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'NS_MISC', 'For natural numbers x, y, and z, if xy + yz = 19 and yz + xz = 51, then the minimum possible value of xyz is', 'tita', NULL, NULL, NULL, NULL, '34', 'y(x+z)=19, and since 19 is prime, either y=19 (forcing x+z=1, impossible for naturals) or y=1, x+z=19. Then z(x+y)=51 gives z(x+1)=51; testing z=3 (x=16) gives xyz=48, and z=17 (x=2) gives xyz=34, the minimum.', NULL, 7, 'medium', 'high', 180, 'Not testing every valid factor pair of 51 for z before concluding which gives the minimum product.'),
  ('CAT2022_QA_S1_20', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'SI_BASIC', 'Alex invested his savings in two parts. The simple interest earned on the first part at 15% per annum for 4 years is the same as the simple interest earned on the second part at 12% per annum for 3 years. Then, the percentage of his savings invested in the first part is', 'mcq', '37.5%', '62.5%', '60%', '40%', 'a', 'x*15*4 = y*12*3, giving 60x=36y, so 5x=3y, i.e. x:y=3:5. Percentage in first part = 3/(3+5)*100 = 37.5%.', NULL, 6, 'low', 'low', 150, 'Not simplifying the ratio 60:36 fully before reading off the proportion of savings.'),
  ('CAT2022_QA_S1_21', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'RATIO_BASIC', 'Pinky is standing in a queue at a ticket counter. Suppose the ratio of the number of persons standing ahead of Pinky to the number of persons standing behind her in the queue is 3:5. If the total number of persons in the queue is less than 300, then the maximum possible number of persons standing ahead of Pinky is', 'tita', NULL, NULL, NULL, NULL, '111', 'With 3a ahead and 5a behind, total = 8a+1 (including Pinky) < 300, giving a<37.375, so maximum a=37. Persons ahead = 3*37 = 111.', NULL, 6, 'low', 'low', 150, 'Forgetting to add 1 for Pinky herself when setting up the total-queue-length inequality.'),
  ('CAT2022_QA_S1_22', 2022, 'Slot 1', 'CAT 2022 Slot 1', TRUE, 'NS_MISC', 'For any real number x, let [x] be the largest integer less than or equal to x. If sum(n=1 to N) [1/5 + n/25] = 25 then N is', 'tita', NULL, NULL, NULL, NULL, '44', 'The floor term [(5+n)/25] equals 0 for n=1 to 19 and 1 for n=20 to 44, since it needs 5+n>=25 (n>=20) and stays at 1 until 5+n<50 (n<45). Summing 25 ones over n=20 to 44 matches the target sum of 25, so N=44.', NULL, 7, 'medium', 'high', 180, 'Miscalculating the boundary values of n where the floor term steps from 0 to 1, or from 1 to 2.'),
  ('CAT2021_QA_S3_01', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'ALG_LINEAR_WORD', 'A shop owner bought a total of 64 shirts from a wholesale market that came in two sizes, small and large. The price of a small shirt was INR 50 less than that of a large shirt. She paid a total of INR 5000 for the large shirts, and a total of INR 1800 for the small shirts. Then, the price of a large shirt and a small shirt together, in INR, is', 'mcq', '175', '150', '200', '225', 'c', 'Let small price = p, large = p+50. Testing option C: large=125, small=75 gives large shirts bought = 5000/125 = 40 and small shirts = 1800/75 = 24, totaling 64. So the sum of prices = 200.', NULL, 6, 'medium', 'medium', 90, 'Forgetting the large=small+50 relation when back-solving from options; not checking that the resulting shirt counts are whole numbers.'),
  ('CAT2021_QA_S3_02', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'TW_COMBINED', 'One day, Rahul started a work at 9 AM and Gautam joined him two hours later. They then worked together and completed the work at 5 PM the same day. If both had started at 9 AM and worked together, the work would have been completed 30 minutes earlier. Working alone, the time Rahul would have taken, in hours, to complete the work is', 'mcq', '11.5', '10', '12.5', '12', 'b', 'Let Rahul''s rate = r and Gautam''s rate = g. Scenario 1: 8r+6g = W. Scenario 2: 7.5(r+g) = W. Equating gives 0.5r = 1.5g, so r = 3g. Then W = 8r+6g = 10r, so Rahul alone takes 10 hours.', NULL, 5, 'medium', 'medium', 60, 'Mixing up who joined late and for how long; using 8 hours instead of 7.5 hours for the second scenario.'),
  ('CAT2021_QA_S3_03', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'PERC_BASIC', 'In a tournament, a team has played 40 matches so far and won 30% of them. If they win 60% of the remaining matches, their overall win percentage will be 50%. Suppose they win 90% of the remaining matches, then the total number of matches won by the team in the tournament will be', 'mcq', '80', '78', '84', '86', 'c', 'Wins so far = 12. Let remaining matches = x. (12+0.6x)/(40+x) = 0.5 gives x = 80. Winning 90% of these: 12+0.9(80) = 84.', NULL, 5, 'medium', 'medium', 60, 'Errors solving for x; forgetting to recompute wins using 90% instead of reusing the 60% figure.'),
  ('CAT2021_QA_S3_04', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'ALG_INEQ_MOD', 'The number of distinct pairs of integers (m,n), satisfying |1 + mn| < |m + n| < 5 is:', 'tita', NULL, NULL, NULL, NULL, '12', 'The first inequality simplifies to (m-1)(n-1) < 0, meaning m and n straddle 1 in a specific pattern. Combined with |m+n| < 5 and integer values, checking along the axes gives the valid pairs (0,±2),(0,±3),(0,±4),(±2,0),(±3,0),(±4,0) — 12 pairs in total.', NULL, 8, 'high', 'high', 150, 'Missing the symmetry across all four quadrants/axes; forgetting the integer-only constraint on m,n.'),
  ('CAT2021_QA_S3_05', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'ALG_LOG_EQ', 'For a real number a, if (log15 a + log32 a) / ((log15 a)(log32 a)) = 4 then a must lie in the range', 'mcq', '2 < a < 3', '3 < a < 4', '4 < a < 5', 'a > 5', 'c', 'Rewriting the LHS in terms of log a reduces the equation to log(480) = 4 log a, i.e., a^4 = 480. Since 4^4=256 and 5^4=625, a lies strictly between 4 and 5.', NULL, 7, 'medium', 'medium', 120, 'Errors converting the mixed-base log expression into a single log a term; not bounding a^4=480 between the right powers.'),
  ('CAT2021_QA_S3_06', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'PERC_SUCCESSIVE', 'The total of male and female populations in a city increased by 25% from 1970 to 1980. During the same period, the male population increased by 40% while the female population increased by 20%. From 1980 to 1990, the female population increased by 25%. In 1990, if the female population is twice the male population, then the percentage increase in the total of male and female populations in the city from 1970 to 1990 is', 'mcq', '68.25', '68.75', '68.50', '69.25', 'b', 'Working backward from the 1990 female:male=2:1 condition using each decade''s growth rates lets you express 1970 populations in terms of a single variable; computing totals for 1970 and 1990 gives an overall increase of 68.75%.', NULL, 7, 'high', 'high', 120, 'Applying the 1980-1990 female growth rate to the wrong base year; confusing which population the initial 25% total growth belongs to.'),
  ('CAT2021_QA_S3_07', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'ALG_RECURRENCE', 'Consider a sequence of real numbers, x1, x2, x3, ... such that x(n+1) = xn + n - 1 for all n >= 1. If x1 = -1 then x100 is equal to', 'mcq', '4849', '4949', '4950', '4850', 'd', 'Sum the recurrence from n = 1 to n = 99: x100 − x1 = Σ(n − 1) = 0 + 1 + 2 + ⋯ + 98 = 98 × 99/2 = 4851. With x1 = −1, x100 = −1 + 4851 = 4850.', NULL, 6, 'medium', 'medium', 90, 'Off-by-one errors in the summation range (1..99 versus 1..100).'),
  ('CAT2021_QA_S3_08', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'NS_MISC', 'The arithmetic mean of scores of 25 students in an examination is 50. Five of these students top the examination with the same score. If the scores of the other students are distinct integers with the lowest being 30, then the maximum possible score of the toppers is', 'tita', NULL, NULL, NULL, NULL, '92', 'Total marks = 1250. To maximize the toppers'' score, minimize the other 20 students'' scores using consecutive distinct integers 30 to 49 (sum=790). The remaining 460 is split equally among 5 toppers: 460/5 = 92.', NULL, 7, 'medium', 'high', 120, 'Not using consecutive integers to minimize the other 20 scores; forgetting all toppers must share the same (maximal) score.'),
  ('CAT2021_QA_S3_09', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'ALG_LINEAR_WORD', 'One part of a hostel''s monthly expenses is fixed, and the other part is proportional to the number of its boarders. The hostel collects ₹1600 per month from each boarder. When the number of boarders is 50, the profit of the hostel is ₹200 per boarder, and when the number of boarders is 75, the profit of the hostel is ₹250 per boarder. When the number of boarders is 80, the total profit of the hostel, in INR, will be', 'mcq', '20200', '20500', '20800', '20000', 'b', 'Let total cost = a+bn. Profit/boarder = 1600-(a/n)-b. Using n=50 and n=75 gives a=7500, b=1250. At n=80, total profit = 80(1600-1250)-7500 = 28000-7500 = 20500.', NULL, 6, 'high', 'medium', 90, 'Building the linear cost equation incorrectly, or forgetting profit/boarder already divides revenue by n.'),
  ('CAT2021_QA_S3_10', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'GEO_MENS_2D', 'The cost of fencing a rectangular plot is ₹200 per ft along one side, and ₹100 per ft along the three other sides. If the area of the rectangular plot is 60000 sq. ft, then the lowest possible cost of fencing all four sides, in INR, is', 'mcq', '120000', '90000', '100000', '160000', 'a', 'With L×B=60000 and the costlier rate assigned to the shorter side B to minimize cost, total cost = 300B+200L = 18000000/L+200L. Applying AM-GM gives a minimum cost of ₹120000.', NULL, 7, 'high', 'high', 120, 'Assigning the higher rate to the wrong (longer) side; not applying AM-GM correctly to the two variable terms.'),
  ('CAT2021_QA_S3_11', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'GEO_MENS_2D', 'A park is shaped like a rhombus and has area 96 sq m. If 40 m of fencing is needed to enclose the park, the cost, in INR, of laying electric wires along its two diagonals, at the rate of ₹125 per m, is', 'tita', NULL, NULL, NULL, NULL, '3500', 'Side = 10m (perimeter/4). Using area = (1/2)d1d2 = 96 and d1²+d2² = (2×side)² = 400, solving gives d1=12, d2=16. Cost = (12+16)×125 = 3500.', NULL, 6, 'medium', 'medium', 90, 'Using side² = d1²+d2² instead of the correct (d1/2)²+(d2/2)² = side² relation.'),
  ('CAT2021_QA_S3_12', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'ALG_LINEAR_WORD', 'A tea shop offers tea in cups of three different sizes. The product of the prices, in INR, of three different sizes is equal to 800. The prices of the smallest size and the medium size are in the ratio 2:5. If the shop owner decides to increase the prices of the smallest and the medium ones by INR 6 keeping the price of the largest size unchanged, the product then changes to 3200. The sum of the original prices of three different sizes, in INR, is', 'tita', NULL, NULL, NULL, NULL, '34', 'Let the prices be 2x, 5x and y, so 10x²y = 800, i.e. x²y = 80. After the increase, (2x+6)(5x+6)y = 3200. Dividing the second equation by the first: (2x+6)(5x+6)/(10x²) = 4, so (2x+6)(5x+6) = 40x². Expanding: 10x² + 42x + 36 = 40x², i.e. 5x² − 7x − 6 = 0, whose positive root is x = 2. The prices are 4, 10, and y = 80/x² = 20, summing to 34.', NULL, 8, 'high', 'high', 150, 'Expansion errors with (2x+6)(5x+6); sign errors in the resulting quadratic in x.'),
  ('CAT2021_QA_S3_13', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'TSD_CIRCULAR', 'Mira and Amal walk along a circular track, starting from the same point at the same time. If they walk in the same direction, then in 45 minutes, Amal completes exactly 3 more rounds than Mira. If they walk in opposite directions, then they meet for the first time exactly after 3 minutes. The number of rounds Mira walks in one hour is', 'tita', NULL, NULL, NULL, NULL, '8', 'Let Mira''s and Amal''s speeds be a and b (in track-lengths per minute). Same direction: 45(b-a)=3 track lengths. Opposite direction: 3(a+b)=1 track length. Solving the ratio gives a = 1/8 track length per minute, so in 60 minutes Mira covers 8 rounds.', NULL, 7, 'high', 'high', 120, 'Not distinguishing relative-speed formulas for same versus opposite direction; unit/time conversion slips.'),
  ('CAT2021_QA_S3_14', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'MIX_ALLIGATION', 'If a certain weight of an alloy of silver and copper is mixed with 3 kg of pure silver, the resulting alloy will have 90% silver by weight. If the same weight of the initial alloy is mixed with 2 kg of another alloy which has 90% silver by weight, the resulting alloy will have 84% silver by weight. Then, the weight of the initial alloy, in kg, is', 'mcq', '3.5', '2.5', '3', '4', 'c', 'Let the initial alloy contain x kg silver and y kg copper. First condition: (x+3)/(x+y+3)=0.9. Second: (x+1.8)/(x+y+2)=0.84 (since the 2kg alloy is 90% silver, it contributes 1.8kg silver). Solving gives x=2.4, y=0.6, so total weight = 3 kg.', NULL, 6, 'high', 'medium', 90, 'Forgetting the second alloy already contains 1.8kg silver (not treating it as pure copper or pure silver).'),
  ('CAT2021_QA_S3_15', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'GEO_TRI_BASIC', 'If a triangle ABC, angle BCA = 50 degrees. D and E are points on AB and AC, respectively, such that AD = DE. If F is a point on BC such that BD = DF, then angle FDE, in degrees, is equal to', 'mcq', '72', '80', '100', '96', 'b', 'Triangles ADE and BDF are isosceles at D. Writing angle ADE = 180-2x and angle BDF = 180-2y (x=angle A, y=angle B), the straight line at D gives angle FDE = 2x+2y-180. Since x+y=130 (triangle angle sum with angle C=50), angle FDE = 80 degrees.', NULL, 7, 'medium', 'high', 120, 'Not recognizing D,E,F form two isosceles triangles sharing vertex D; sign errors in the straight-angle equation at D.'),
  ('CAT2021_QA_S3_16', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'CI_ANNUAL', 'Bank A offers 6% interest rate per annum compounded half-yearly. Bank B and Bank C offer simple interest but the annual interest rate offered by Bank C is twice that of Bank B. Raju invests a certain amount in Bank B for a certain period and Rupa invests ₹10,000 in Bank C for twice that period. The interest that would accrue to Raju during that period is equal to the interest that would have accrued had he invested the same amount in Bank A for one year. The interest accrued, in INR, to Rupa is', 'mcq', '3436', '2436', '2346', '1436', 'b', 'Bank A''s effective annual rate is (1.03)^2-1=6.09%. Setting Raju''s SI in Bank B equal to this gives (x/100)t=0.0609. Rupa''s interest in Bank C over 2t years at rate 2x% is 10000×2t×(2x/100)=40000×(x/100)t=40000×0.0609=2436.', NULL, 8, 'high', 'medium', 150, 'Using a flat 6% instead of the compounded half-yearly effective rate; mismatching Raju''s and Rupa''s investment periods.'),
  ('CAT2021_QA_S3_17', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'ALG_FUNC_OPT', 'If f(x) = x^2 - 7x and g(x) = x + 3, then the minimum value of f(g(x)) - 3x is:', 'mcq', '-20', '-12', '-15', '-16', 'd', 'f(g(x))-3x = (x+3)^2-7(x+3)-3x = x^2-4x-12. The minimum occurs at x=2, giving 4-8-12 = -16.', NULL, 5, 'low', 'medium', 60, 'Forgetting to subtract the extra -3x term before minimizing the resulting quadratic.'),
  ('CAT2021_QA_S3_18', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'TW_WAGES', 'Anil can paint a house in 12 days while Barun can paint it in 16 days. Anil, Barun, and Chandu undertake to paint the house for ₹24000 and the three of them together complete the painting in 6 days. If Chandu is paid in proportion to the work done by him, then the amount in INR received by him is', 'tita', NULL, NULL, NULL, NULL, '3000', 'Using total work=48 units (LCM of 12,16,6), Anil contributes 4 units/day and Barun 3 units/day; over 6 days they together do 42 units, leaving 6 units (1/8 of the work) for Chandu, so he earns 24000/8=3000.', NULL, 5, 'medium', 'medium', 60, 'Forgetting to subtract Anil and Barun''s combined 6-day contribution before finding Chandu''s share.'),
  ('CAT2021_QA_S3_19', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'ALG_EXP', 'If n is a positive integer such that (10^(1/7))(10^(2/7))...(10^(n/7)) > 999, then the smallest value of n is', 'tita', NULL, NULL, NULL, NULL, '6', 'The product is 10^[(1 + 2 + ⋯ + n)/7] = 10^[n(n+1)/14]. For the product to exceed 999 the exponent must exceed log(999) ≈ 2.9996. At n = 5 the exponent is 30/14 ≈ 2.143 (about 139, too small); at n = 6 it is 42/14 = 3 exactly, giving 1000 > 999. So the smallest n is 6.', NULL, 6, 'medium', 'medium', 90, 'Miscalculating the sum of exponents 1+2+...+n divided by 7; not verifying n=5 actually fails.'),
  ('CAT2021_QA_S3_20', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'MOD_LINEAR', 'A four-digit number is formed by using only the digits 1, 2 and 3 such that both 2 and 3 appear at least once. The number of all such four-digit numbers is', 'tita', NULL, NULL, NULL, NULL, '50', 'Total 4-digit strings from {1,2,3} = 3^4=81. By inclusion-exclusion, subtract those missing 2 (16), missing 3 (16), and add back those missing both (1): 81-16-16+1=50.', NULL, 7, 'medium', 'high', 120, 'Forgetting the inclusion-exclusion correction term (adding back the doubly-excluded case).'),
  ('CAT2021_QA_S3_21', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'GEO_QUAD', 'Let ABCD be a parallelogram. The lengths of the side AD and the diagonal AC are 10cm and 20cm, respectively. If the angle ADC is equal to 30 degrees then the area of the parallelogram, in sq.cm is', 'mcq', '25(sqrt5+sqrt15)/2', '25(sqrt3+sqrt15)', '25(sqrt3+sqrt15)/2', '25(sqrt5+sqrt15)', 'b', 'In triangle ACD, the cosine rule with AD=10, AC=20, angle ADC=30 degrees gives CD^2-10*sqrt3*CD-300=0, so CD=(10sqrt3+10sqrt15)/2. Using CD as base with the corresponding height (via sine rule) gives parallelogram area = 25(sqrt3+sqrt15).', NULL, 8, 'high', 'high', 150, 'Applying the cosine rule to the wrong triangle or angle; sign/root errors solving the resulting quadratic in CD.'),
  ('CAT2021_QA_S3_22', 2021, 'Slot 3', 'CAT 2021 Slot 3 (Cracku PYQ compilation)', TRUE, 'ALG_SPECIAL', 'If 3x + 2|y| + y = 7 and x + |x| + 3y = 1 then x + 2y is:', 'mcq', '-4/3', '8/3', '0', '1', 'c', 'Testing sign cases, x>=0 and y<0 works: the equations reduce to 3x-y=7 and 2x+3y=1, giving x=2, y=-1, so x+2y=0.', NULL, 8, 'medium', 'high', 150, 'Not systematically testing all four sign-case combinations for x and y before solving.'),
  ('CAT2021_QA_S2_01', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'ALG_EXP', 'For all possible integers n satisfying 2.25 <= 2 + 2^(n+2) <= 202, then the number of integer values of 3 + 3^(n+1) is:', 'tita', NULL, NULL, NULL, NULL, '7', 'The first inequality gives 0.25<=2^(n+2)<=200, so -4<=n<=5. But 3^(n+1) is only an integer for n>=-1, restricting valid n to -1,0,1,2,3,4,5 — 7 values.', NULL, 6, 'medium', 'medium', 90, 'Forgetting that the second expression requires n>=-1 for an integer power of 3.'),
  ('CAT2021_QA_S2_02', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'ALG_AP', 'Three positive integers x, y and z are in arithmetic progression. If y - x > 2 and xyz = 5(x + y + z), then z-x equals', 'mcq', '8', '12', '14', '10', 'c', 'With x=a, y=a+d, z=a+2d, the product condition simplifies to a(a+2d)=15. Since d>2 and all terms are positive integers, the only valid factor pair is a=1, a+2d=15, so z-x=2d=14.', NULL, 7, 'medium', 'high', 120, 'Not restricting factor pairs of 15 to those consistent with d>2.'),
  ('CAT2021_QA_S2_03', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'NS_MISC', 'For a 4-digit number, the sum of its digits in the thousands, hundreds and tens places is 14, the sum of its digits in the hundreds, tens and units places is 15, and the tens place digit is 4 more than the units place digit. Then the highest possible 4-digit number satisfying the above conditions is', 'tita', NULL, NULL, NULL, NULL, '4195', 'With digits a,b,c,d: a+b+c=14, b+c+d=15, c=d+4. Subtracting the first two gives d=a+1. Maximizing a (thousands digit) subject to c<=9 gives c=9, d=5, a=4, b=1, forming 4195.', NULL, 7, 'medium', 'high', 120, 'Not maximizing the thousands digit first before fixing the others; exceeding single-digit bounds.'),
  ('CAT2021_QA_S2_04', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'PERC_SUCCESSIVE', 'Raj invested ₹10000 in a fund. At the end of first year, he incurred a loss but his balance was more than ₹5000. This balance, when invested for another year, grew and the percentage of growth in the second year was five times the percentage of loss in the first year. If the gain of Raj from the initial investment over the two year period is 35%, then the percentage of loss in the first year is', 'mcq', '5', '15', '17', '10', 'd', 'Let loss=x%. Final amount = 10000(1-x/100)(1+5x/100)=13500. Solving 5x^2-400x+3500=0 gives x=10 or x=70; since balance>5000 means x<50, x=10.', NULL, 7, 'high', 'medium', 120, 'Not rejecting the x=70 root using the ''balance greater than ₹5000'' constraint.'),
  ('CAT2021_QA_S2_05', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'MOD_DISTRIBUTION', 'The number of ways of distributing 15 identical balloons, 6 identical pencils and 3 identical erasers among 3 children, such that each child gets at least four balloons and one pencil, is', 'tita', NULL, NULL, NULL, NULL, '1000', 'After giving each child the guaranteed minimum (4 balloons, 1 pencil), distribute the remaining 3 balloons, 3 pencils, and 3 erasers among 3 children using stars-and-bars (5C2=10 ways for each item type), giving 10x10x10=1000.', NULL, 7, 'medium', 'medium', 120, 'Forgetting to subtract the guaranteed minimum allocation before applying stars-and-bars.'),
  ('CAT2021_QA_S2_06', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'TSD_TRAIN', 'Two trains A and B were moving in opposite directions, their speeds being in the ratio 5:3. The front end of A crossed the rear end of B 46 seconds after the front ends of the trains had crossed each other. It took another 69 seconds for the rear ends of the trains to cross each other. The ratio of length of train A to that of train B is', 'mcq', '3:2', '5:3', '2:3', '2:1', 'a', 'In the 46s after front ends meet, train A''s front covers train B''s length at the relative speed, so Length(B)=46x(relative speed). In the next 69s, train B covers train A''s length: Length(A)=69x(relative speed). Ratio A:B=69:46=3:2.', NULL, 7, 'medium', 'medium', 120, 'Mixing up which train''s length corresponds to which of the two time intervals.'),
  ('CAT2021_QA_S2_07', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'ALG_QUAD_ROOT', 'Suppose one of the roots of the equation ax^2 - bx + c = 0 is 2 + sqrt(3), Where a,b and c are rational numbers and a != 0. If b = c^3 then |a| equals.', 'mcq', '1', '2', '3', '4', 'b', 'Since coefficients are rational, the other root is the conjugate 2-sqrt(3). Sum of roots=4=b/a, product=1=c/a, so b=4a, c=a. From b=c^3: 4a=a^3, giving a^2=4, so |a|=2.', NULL, 7, 'medium', 'high', 120, 'Forgetting that rational coefficients force the conjugate root; sign errors solving a^2=4.'),
  ('CAT2021_QA_S2_08', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'MIX_REPLACEMENT', 'From a container filled with milk, 9 litres of milk are drawn and replaced with water. Next, from the same container, 9 litres are drawn and again replaced with water. If the volumes of milk and water in the container are now in the ratio of 16:9, then the capacity of the container, in litres, is', 'tita', NULL, NULL, NULL, NULL, '45', 'Using the replacement formula, final milk fraction = (1-9/V)^2 = 16/25, so 1-9/V=4/5 (rejecting the negative root), giving V=45.', NULL, 7, 'medium', 'medium', 120, 'Not rejecting the extraneous negative-root solution (V=5, which is physically impossible since 9L is drawn each time).'),
  ('CAT2021_QA_S2_09', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'GEO_MENS_2D', 'If a rhombus has area 12 sq cm and side length 5 cm, then the length, in cm, of its longer diagonal is', 'mcq', 'sqrt37+sqrt13', 'sqrt13+sqrt12', '(sqrt37+sqrt13)/2', '(sqrt13+sqrt12)/2', 'a', 'With diagonals d1,d2: d1^2+d2^2=100 (from side=5) and d1*d2=24 (from area=12). Solving (d1+d2)^2=148 and (d1-d2)^2=52 gives the longer diagonal d1=sqrt37+sqrt13.', NULL, 8, 'high', 'high', 150, 'Confusing the sum-of-squares identity linking d1+d2, d1-d2 to the side length and area.'),
  ('CAT2021_QA_S2_10', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'ALG_LOG_EQ', 'If log2[3 + log3 {4 + log4(x - 1)}] - 2 = 0 then 4x equals', 'tita', NULL, NULL, NULL, NULL, '5', 'Working from the outside in: log3{4+log4(x-1)}=1, so 4+log4(x-1)=3, giving log4(x-1)=-1, so x-1=1/4, x=5/4, and 4x=5.', NULL, 6, 'medium', 'medium', 90, 'Sign errors unwinding nested logarithms from outside to inside.'),
  ('CAT2021_QA_S2_11', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'GEO_TRAP', 'The sides AB and CD of a trapezium ABCD are parallel, with AB being the smaller side. P is the midpoint of CD and ABPD is a parallelogram. If the difference between the areas of the parallelogram ABPD and the triangle BPC is 10 sq cm, then the area, in sq cm, of the trapezium ABCD is', 'mcq', '30', '40', '25', '20', 'a', 'Let DP=AB=x and height=h. Area(ABPD)=xh, Area(BPC)=xh/2, so their difference xh/2=10 gives xh=20. Trapezium area = (1/2)(AB+CD)h = (1/2)(x+2x)h = 1.5xh = 30.', NULL, 6, 'medium', 'medium', 90, 'Not recognizing CD=2xDP since P is the midpoint; confusing which region is being subtracted.'),
  ('CAT2021_QA_S2_12', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'ALG_FUNC_DOMAIN', 'For all real values of x, the range of the function f(x) = (x^2+2x+4)/(2x^2+4x+9) is:', 'mcq', '[4/9, 8/9]', '[3/7, 8/9)', '(3/7, 1/2)', '[3/7, 1/2)', 'd', 'Rewrite f(x) = 1/2 - 0.5/(2x^2+4x+9). Since 2x^2+4x+9 has a minimum of 7 (at x=-1) and grows without bound, f(x) ranges from 3/7 (attained at x=-1) up to but never reaching 1/2 (approached as x tends to infinity).', NULL, 8, 'high', 'high', 150, 'Not isolating a single reusable quadratic term when splitting the fraction; missing that 1/2 is an unattained (open) bound.'),
  ('CAT2021_QA_S2_13', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'ALG_SERIES_SPECIAL', 'For a sequence of real numbers x1, x2, ...xn, If x1 - x2 + x3 - .... + (-1)^(n+1)xn = n^2 + 2n for all natural numbers n, then the sum x49 + x50 equals', 'mcq', '200', '2', '-200', '-2', 'd', 'Comparing consecutive partial sums gives the general term xn=(-1)^(n+1)(2n+1). So x49=99 and x50=-101, giving x49+x50=-2.', NULL, 7, 'medium', 'high', 120, 'Sign errors deriving xn from Sn - S(n-1) for consecutive n.'),
  ('CAT2021_QA_S2_14', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'ALG_INEQ_MOD', 'For a real number x the condition |3x - 20| + |3x - 40| = 20 necessarily holds if', 'mcq', '10<x<15', '9<x<14', '7<x<12', '6<x<11', 'c', 'The equation holds exactly for 20/3<=x<=40/3 (approximately 6.67 to 13.33). This full range contains, and therefore necessarily implies, the narrower option 7<x<12.', NULL, 6, 'medium', 'high', 90, 'Confusing ''necessarily holds'' (looking for a subset range) with the actual full solution range of the equation.'),
  ('CAT2021_QA_S2_15', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'TW_WAGES', 'Anil can paint a house in 60 days while Bimal can paint it in 84 days. Anil starts painting and after 10 days, Bimal and Charu join him. Together, they complete the painting in 14 more days. If they are paid a total of ₹21000 for the job, then the share of Charu, in INR, proportionate to the work done by him, is', 'mcq', '9000', '9200', '9100', '9150', 'c', 'Using total work=420 units (LCM of 60,84), Anil works 24 days total (168 units) and Bimal works 14 days (70 units); Charu''s share = 420-168-70 = 182 units, i.e., 13/30 of the pay = (13/30)x21000 = 9100.', NULL, 6, 'high', 'medium', 90, 'Forgetting Anil also works during the final 14 days on top of his initial 10-day head start.'),
  ('CAT2021_QA_S2_16', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'PERC_BASIC', 'A box has 450 balls, each either white or black, there being as many metallic white balls as metallic black balls. If 40% of the white balls and 50% of the black balls are metallic, then the number of non-metallic balls in the box is', 'tita', NULL, NULL, NULL, NULL, '250', 'With white=x, black=y: x+y=450 and 0.4x=0.5y. Solving gives x=250, y=200. Non-metallic balls = 0.6x+0.5y = 150+100 = 250.', NULL, 6, 'medium', 'medium', 90, 'Setting up the ''equal metallic balls'' condition incorrectly, e.g. equating totals instead of the metallic subsets.'),
  ('CAT2021_QA_S2_17', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'NS_MISC', 'In a football tournament, a player has played a certain number of matches and 10 more matches are to be played. If he scores a total of one goal over the next 10 matches, his overall average will be 0.15 goals per match. On the other hand, if he scores a total of two goals over the next 10 matches, his overall average will be 0.2 goals per match. The number of matches he has played is', 'tita', NULL, NULL, NULL, NULL, '10', 'Let matches played=n, goals so far=x. (x+1)/(n+10)=0.15 and (x+2)/(n+10)=0.2. Subtracting: 1/(n+10)=0.05, so n+10=20, n=10.', NULL, 6, 'low', 'medium', 90, 'Not noticing both equations share the same denominator (n+10), which allows a quick subtraction.'),
  ('CAT2021_QA_S2_18', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'MIX_ALLIGATION', 'A person buys tea of three different qualities at ₹800, ₹500, and ₹300 per kg, respectively, and the amounts bought are in the proportion 2:3:5. She mixes all the tea and sells one-sixth of the mixture at ₹700 per kg. The price, in INR per kg, at which she should sell the remaining tea, to make an overall profit of 50%, is', 'mcq', '653', '688', '692', '675', 'b', 'Taking quantities 12,18,30 kg, total cost=₹27600 for 60kg. Target revenue for 50% overall profit=₹41400. Selling one-sixth (10kg) at ₹700 gives ₹7000, leaving ₹34400 to be earned from the remaining 50kg, i.e., ₹688/kg.', NULL, 7, 'medium', 'medium', 120, 'Computing profit on the wrong base, or miscalculating one-sixth of the 60kg total mixture.'),
  ('CAT2021_QA_S2_19', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'ALG_LINEAR_2', 'Consider the pair of equations: x^2 - xy - x = 22 and y^2 - xy + y = 34. If x > y, then x - y equals', 'mcq', '6', '4', '7', '8', 'd', 'Adding both equations gives x^2-2xy+y^2-x+y=56, i.e., (x-y)^2-(x-y)=56. Setting t=x-y: t^2-t-56=0 factors as (t-8)(t+7)=0. Since x>y, t=8.', NULL, 8, 'medium', 'high', 150, 'Not recognizing that adding the two equations forms a perfect-square-minus-linear expression in (x-y).'),
  ('CAT2021_QA_S2_20', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'GEO_TRI_AREA', 'Let D and E be points on sides AB and AC, respectively, of a triangle ABC, such that AD:BD = 2:1 and AE:CE = 2:3. If the area of the triangle ADE is 8 sq cm, then the area of the triangle ABC, in sq cm, is', 'tita', NULL, NULL, NULL, NULL, '30', 'With AD=2x, AE=2y (so AB=3x, AC=5y), Area(ADE)=(1/2)(2x)(2y)sinA=8 gives xy*sinA=4. Area(ABC)=(1/2)(3x)(5y)sinA=7.5xy*sinA=7.5x4=30.', NULL, 7, 'medium', 'high', 120, 'Using AD and AE as the full side lengths instead of adding the remaining segment to get AB and AC.'),
  ('CAT2021_QA_S2_21', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'PART_BASIC', 'Anil, Bobby, and Chintu jointly invest in a business and agree to share the overall profit in proportion to their investments. Anil''s share of investment is 70%. His share of profit decreases by ₹420 if the overall profit goes down from 18% to 15%. Chintu''s share of profit increases by ₹80 if the overall profit goes up from 15% to 17%. The amount, in INR, invested by Bobby is', 'mcq', '2000', '2400', '2200', '1800', 'a', 'A 3% swing in overall profit corresponds to ₹420 for Anil''s 70% share, so 3% of total investment=420x(10/7)=₹600, giving total investment=₹20000. Chintu''s ₹80 corresponds to 20% of a 2%-profit swing (₹400), so Chintu invested 20% (₹4000); Bobby then invested the remaining 10%=₹2000.', NULL, 8, 'high', 'high', 150, 'Not correctly converting the rupee changes into percentage-of-total-investment shares for each partner.'),
  ('CAT2021_QA_S2_22', 2021, 'Slot 2', 'CAT 2021 Slot 2 (Cracku PYQ compilation)', TRUE, 'PIPE_LEAK', 'Two pipes A and B are attached to an empty water tank. Pipe A fills the tank while pipe B drains it. If pipe A is opened at 2 pm and pipe B is opened at 3 pm, then the tank becomes full at 10 pm. Instead, if pipe A is opened at 2 pm and pipe B is opened at 4 pm, then the tank becomes full at 6 pm. If pipe B is not opened at all, then the time, in minutes, taken to fill the tank is', 'mcq', '144', '140', '264', '120', 'a', 'With A''s rate x and B''s rate y, tank volume V=8x-7y (first scenario) = 4x-2y (second scenario). Solving gives y=4x/5, so V=12x/5. Time for A alone = V/x = 12/5 hours = 144 minutes.', NULL, 8, 'high', 'high', 150, 'Miscounting how many hours each pipe runs in each of the two scenarios.'),
  ('CAT2021_QA_S1_01', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'TSD_TRAIN', 'Two trains cross each other in 14 seconds when running in opposite directions along parallel tracks. The faster train is 160 m long and crosses a lamp post in 12 seconds. If the speed of the other train is 6 km/hr less than the faster one, its length, in m, is', 'mcq', '184', '192', '190', '180', 'c', 'Faster train''s speed = 160/12 = 40/3 m/s. Slower train''s speed = 40/3 - 6x(5/18) = 35/3 m/s. Combined speed = 25 m/s. If slower train''s length = x: (160+x)/25=14, giving x=190.', NULL, 6, 'medium', 'medium', 90, 'Forgetting to convert 6 km/hr to m/s before subtracting from the faster train''s speed.'),
  ('CAT2021_QA_S1_02', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'GEO_POLY', 'If the area of a regular hexagon is equal to the area of an equilateral triangle of side 12 cm, then the length, in cm, of each side of the hexagon is', 'mcq', '4sqrt6', '6sqrt6', 'sqrt6', '2sqrt6', 'd', 'Area of hexagon (side x) = (3sqrt3/2)x^2; area of triangle (side 12) = (sqrt3/4)(144). Equating and simplifying gives x^2=24, so x=2sqrt6.', NULL, 5, 'medium', 'medium', 60, 'Using the wrong area-formula constant for a regular hexagon.'),
  ('CAT2021_QA_S1_03', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'GEO_POLY', 'Suppose the length of each side of a regular hexagon ABCDEF is 2 cm. If T is the mid point of CD, then the length of AT, in cm, is', 'mcq', 'sqrt13', 'sqrt14', 'sqrt12', 'sqrt15', 'a', 'AD (a long diagonal) = 4, DT = 1, and angle ADT = 60 degrees (since AD bisects the hexagon symmetrically). By the cosine rule, AT^2=16+1-2(4)(1)cos60=13, so AT=sqrt13.', NULL, 6, 'medium', 'high', 90, 'Using the wrong angle at D; not recognizing AD splits the hexagon into two symmetric halves.'),
  ('CAT2021_QA_S1_04', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'TW_ALTERNATE', 'Anu, Vinu and Manu can complete a work alone in 15 days, 12 days and 20 days, respectively. Vinu works everyday. Anu works only on alternate days starting from the first day while Manu works only on alternate days starting from the second day. Then, the number of days needed to complete the work is', 'mcq', '5', '8', '6', '7', 'd', 'Using total work=60 units (Anu=4/day, Vinu=5/day, Manu=3/day), day 1 (Anu+Vinu)=9 units, day 2 (Manu+Vinu)=8 units, repeating. After 6 days, 51 units are done; day 7 (Anu+Vinu) adds exactly the remaining 9 units, finishing the work on day 7.', NULL, 6, 'medium', 'medium', 90, 'Not tracking the alternating work pattern correctly across days.'),
  ('CAT2021_QA_S1_05', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'ALG_LINEAR_WORD', 'The amount Neeta and Geeta together earn in a day equals what Sita alone earns in 6 days. The amount Sita and Neeta together earn in a day equals what Geeta alone earns in 2 days. The ratio of the daily earnings of the one who earns the most to that of the one who earns the least is', 'mcq', '3:2', '11:7', '11:3', '7:3', 'c', 'Let daily earnings be n,g,s. n+g=6s and s+n=2g. Subtracting gives 7s=3g. Setting g=7a, s=3a gives n=6s-g=18a-7a=11a. Ratio of highest (n=11a) to lowest (s=3a) is 11:3.', NULL, 6, 'medium', 'medium', 90, 'Errors solving the two simultaneous equations for the ratio between g, s, n.'),
  ('CAT2021_QA_S1_06', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'MIX_ALLIGATION', 'Onion is sold for 5 consecutive months at the rate of Rs 10, 20, 25, 25, and 50 per kg, respectively. A family spends a fixed amount of money on onion for each of the first three months, and then spends half that amount on onion for each of the next two months. The average expense for onion, in rupees per kg, for the family over these 5 months is closest to', 'mcq', '26', '18', '16', '20', 'b', 'Assuming ₹100 spent each of the first 3 months and ₹50 each of the next 2, quantities bought are 10,5,4,2,1 kg (22kg total) for ₹400 total spend. Average = 400/22 ≈ 18.18, closest to 18.', NULL, 6, 'medium', 'medium', 90, 'Averaging the five per-kg prices directly instead of computing a spend-weighted average.'),
  ('CAT2021_QA_S1_07', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'MOD_SELECT', 'The number of groups of three or more distinct numbers that can be chosen from 1, 2, 3, 4, 5, 6, 7 and 8 so that the groups always include 3 and 5, while 7 and 8 are never included together is', 'tita', NULL, NULL, NULL, NULL, '47', 'With 3 and 5 fixed, choose additional numbers from {1,2,4,6,7,8} such that 7 and 8 aren''t both selected, with at least one extra number to reach group size 3. Counting selections by group size (of the remaining 6 numbers) while excluding the both-7-and-8 cases and the empty selection gives 47 valid groups.', NULL, 8, 'high', 'high', 150, 'Forgetting the minimum group-size-3 constraint requires at least one number beyond 3 and 5; double-handling the 7-and-8-together exclusion.'),
  ('CAT2021_QA_S1_08', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'PL_CP_SP', 'Amal purchases some pens at ₹8 each. To sell these, he hires an employee at a fixed wage. He sells 100 of these pens at ₹12 each. If the remaining pens are sold at ₹11 each, then he makes a net profit of ₹300, while he makes a net loss of ₹300 if the remaining pens are sold at ₹9 each. The wage of the employee, in INR, is', 'tita', NULL, NULL, NULL, NULL, '1000', 'Let total pens=n, wage=W. Case 1: 1200+11(n-100)-8n-W=300, giving 3n-W=200. Case 2: 1200+9(n-100)-8n-W=-300, giving W-n=600. Adding the two: 2n=800, n=400, so W=1000.', NULL, 7, 'medium', 'medium', 120, 'Sign errors setting up the profit versus loss equations.'),
  ('CAT2021_QA_S1_09', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'ALG_LINEAR_WORD', 'A basket of 2 apples, 4 oranges and 6 mangoes costs the same as a basket of 1 apple, 4 oranges and 8 mangoes, or a basket of 8 oranges and 7 mangoes. Then the number of mangoes in a basket of mangoes that has the same cost as the other baskets is', 'mcq', '11', '13', '10', '12', 'b', 'From the first two baskets: 2a+6m=a+8m, so a=2m. From the second and third: a+4o+8m=8o+7m, so a+m=4o, giving o=3m/4. Total cost = a+4o+8m = 2m+3m+8m = 13m.', NULL, 6, 'medium', 'medium', 90, 'Errors substituting the a=2m relation into the second basket equation.'),
  ('CAT2021_QA_S1_10', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'ALG_INEQ_MOD', 'The number of integers n that satisfy the inequalities |n - 60| < |n - 100| < |n - 20| is', 'mcq', '21', '19', '18', '20', 'b', 'The distance conditions together force 60<n<80. The integers 61 through 79 satisfy all conditions, giving 19 values.', NULL, 7, 'medium', 'high', 120, 'Misinterpreting which reference point (60, 100, or 20) n must lie closer to from each part of the chained inequality.'),
  ('CAT2021_QA_S1_11', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'NS_MISC', 'How many three-digit numbers are greater than 100 and increase by 198 when the three digits are arranged in the reverse order?', 'tita', NULL, NULL, NULL, NULL, '70', 'For number abc, reversing gives cba. (100c+10b+a)-(100a+10b+c)=198 simplifies to c-a=2. Since a ranges 1-7 (so c=a+2 stays a valid digit), there are 7 choices for (a,c), and b is unconstrained (10 choices), giving 7x10=70.', NULL, 5, 'low', 'medium', 60, 'Forgetting the middle digit b is free to be any of 10 digits, contributing a multiplying factor of 10.'),
  ('CAT2021_QA_S1_12', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'CI_ANNUAL', 'Anil invests some money at a fixed rate of interest, compounded annually. If the interests accrued during the second and third year are ₹806.25 and ₹866.72, respectively, the interest accrued, in INR, during the fourth year is nearest to', 'mcq', '929.48', '934.65', '931.72', '926.84', 'c', 'The ratio of consecutive years'' interest equals (1+r), so r = 866.72/806.25 - 1 ≈ 0.075 (7.5%). Interest in year 4 = 866.72x1.075 ≈ 931.72.', NULL, 8, 'medium', 'medium', 150, 'Treating the ratio of interests as r directly instead of as (1+r).'),
  ('CAT2021_QA_S1_13', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'NS_MISC', 'Suppose hospital A admitted 21 less Covid infected patients than hospital B, and all eventually recovered. The sum of recovery days for patients in hospitals A and B were 200 and 152, respectively. If the average recovery days for patients admitted in hospital A was 3 more than the average in hospital B then the number admitted in hospital A was', 'tita', NULL, NULL, NULL, NULL, '35', 'Let hospital A admit x patients (B admits x+21). 200/x - 152/(x+21) = 3. Solving the resulting quadratic x^2+5x-1400=0 gives x=35 (rejecting the negative root).', NULL, 7, 'high', 'medium', 120, 'Reversing hospital A''s and B''s patient counts; not rejecting the negative root of the quadratic.'),
  ('CAT2021_QA_S1_14', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'GEO_TRI_CENTERS', 'A circle of diameter 8 inches is inscribed in a triangle ABC where angle ABC = 90 degrees. If BC = 10 inches then the area of the triangle in square inches is', 'tita', NULL, NULL, NULL, NULL, '120', 'Inradius=4. For a right triangle with legs AB, BC=10 and hypotenuse AC, the inradius formula r=(AB+BC-AC)/2=4, combined with Pythagoras AB^2+100=AC^2, gives AB=24. Area = (1/2)x10x24 = 120.', NULL, 7, 'high', 'high', 120, 'Misapplying the inradius formula for a right triangle (r = (leg1+leg2-hypotenuse)/2).'),
  ('CAT2021_QA_S1_15', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'ALG_INEQ_QUAD', 'f(x) = (x^2+2x-15)/(x^2-7x-18) is negative if and only if', 'mcq', '-5<x<-2 or 3<x<9', 'x<-5 or -2<x<3', '-2<x<3 or x>9', 'x<-5 or 3<x<9', 'a', 'Factoring gives f(x)=(x+5)(x-3)/[(x-9)(x+2)]. Checking sign changes at the four roots -5,-2,3,9 shows the expression is negative exactly on (-5,-2) and (3,9).', NULL, 7, 'medium', 'high', 120, 'Sign-chart errors, especially mixing up numerator versus denominator roots when tracking sign flips.'),
  ('CAT2021_QA_S1_16', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'ALG_LOG_EQ', 'If 5 - log10 sqrt(1+x) + 4 log10 sqrt(1-x) = log10 (1/sqrt(1-x^2)), then 100x equals', 'tita', NULL, NULL, NULL, NULL, '99', 'Rewriting the RHS as -log sqrt(1+x) - log sqrt(1-x) and simplifying leads to 5 = -5 log sqrt(1-x), so log sqrt(1-x) = -1, sqrt(1-x)=1/10, 1-x=1/100, x=99/100, and 100x=99.', NULL, 8, 'high', 'high', 150, 'Sign errors combining the logarithmic terms on both sides of the equation.'),
  ('CAT2021_QA_S1_17', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'TW_COMBINED', 'Amar, Akbar and Anthony are working on a project. Working together Amar and Akbar can complete the project in 1 year, Akbar and Anthony can complete in 16 months, Anthony and Amar can complete in 2 years. If the person who is neither the fastest nor the slowest works alone, the time in months he will take to complete the project is', 'tita', NULL, NULL, NULL, NULL, '32', 'Using total work=48 units (LCM of 12,16,24): Amar+Akbar=4/month, Akbar+Anthony=3/month, Anthony+Amar=2/month. Solving gives Amar=1.5, Akbar=2.5, Anthony=0.5 units/month. The middle worker Amar takes 48/1.5=32 months alone.', NULL, 7, 'high', 'high', 120, 'Solving the three simultaneous work-rate equations incorrectly; misidentifying which person is the ''middle'' one.'),
  ('CAT2021_QA_S1_18', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'ALG_RECURRENCE', 'If x0 = 1, x1 = 2, and x(n+2) = (1+x(n+1))/xn, n = 0,1,2,3,......, then x2021 is equal to', 'mcq', '4', '1', '3', '2', 'd', 'Computing terms: x2=3, x3=2, x4=1, x5=1, x6=2 -- the sequence is periodic with period 5 starting from x1. Since 2021=5x404+1, x2021=x1=2.', NULL, 7, 'medium', 'high', 120, 'Not spotting the periodicity, or miscalculating the offset when reducing 2021 mod 5.'),
  ('CAT2021_QA_S1_19', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'MIX_REPLACEMENT', 'The strength of an indigo solution in percentage is equal to the amount of indigo in grams per 100 cc of water. Two 800 cc bottles are filled with indigo solutions of strengths 33% and 17%, respectively. A part of the solution from the first bottle is thrown away and replaced by an equal volume of the solution from the second bottle. If the strength of the indigo solution in the first bottle has now changed to 21% then the volume, in cc, of the solution left in the second bottle is', 'tita', NULL, NULL, NULL, NULL, '200', 'By alligation, the mixing ratio of bottle1''s remaining part to bottle2''s added part is (21-17):(33-21)=4:12=1:3. So 3 parts of the 800cc from bottle 2 (600cc) get transferred, leaving 200cc in bottle 2.', NULL, 7, 'medium', 'high', 120, 'Inverting the alligation ratio, i.e., mixing up which strength corresponds to which ''part''.'),
  ('CAT2021_QA_S1_20', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'PERC_BASIC', 'Identical chocolate pieces are sold in boxes of two sizes, small and large. The large box is sold for twice the price of the small box. If the selling price per gram of chocolate in the large box is 12% less than that in the small box, then the percentage by which the weight of chocolate in the large box exceeds that in the small box is nearest to', 'mcq', '144', '127', '135', '124', 'b', 'Let small box price=100, weight=S; large box price=200, weight=L. Price/gram: 200/L=0.88x(100/S), giving L/S=25/11≈2.27, i.e., about 127% more chocolate in the large box.', NULL, 8, 'medium', 'medium', 150, 'Reporting L/S directly as the percentage excess instead of (L/S-1)x100.'),
  ('CAT2021_QA_S1_21', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'ALG_SERIES_SPECIAL', 'The natural numbers are divided into groups as (1), (2, 3, 4), (5, 6, 7, 8, 9), ... and so on. Then, the sum of the numbers in the 15th group is equal to', 'mcq', '6119', '6090', '4941', '7471', 'a', 'The last number of the nth group is n^2. Group 15 runs from 14^2+1=197 to 15^2=225, spanning 29 consecutive integers. Their sum = 29x(197+225)/2 = 6119.', NULL, 7, 'medium', 'high', 120, 'Miscalculating the first term of the 15th group (should be (n-1)^2+1).'),
  ('CAT2021_QA_S1_22', 2021, 'Slot 1', 'CAT 2021 Slot 1 (Cracku PYQ compilation)', TRUE, 'ALG_QUAD_ROOT', 'If r is a constant such that |x^2 - 4x - 13| = r has exactly three distinct real roots, then the value of r is', 'mcq', '17', '21', '15', '18', 'a', 'Exactly 3 roots occurs only when one branch of the reflected graph is tangent to y=r, i.e., when the discriminant of x^2-4x-13+r=0 is zero: 68-4r=0, giving r=17. (This corresponds to r equalling the negative of the parabola''s minimum value, -(-17)=17.)', NULL, 8, 'high', 'high', 150, 'Not recognizing that exactly three roots only occurs at the specific r where one branch''s discriminant is exactly zero (tangency at the vertex reflection).'),
  ('CAT2020_QA_S3_1', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'MIX_ALLIGATION', 'Two alcohol solutions, A and B, are mixed in the proportion 1:3 by volume. The volume of the mixture is then doubled by adding solution A such that the resulting mixture has 72% alcohol. If solution A has 60% alcohol, then the percentage of alcohol in solution B is', 'mcq', '90%', '94%', '92%', '89%', 'c', 'Doubling the volume by adding A means A is added in equal volume to the original mix, i.e. mixed 1:1. Using the average rule on this 1:1 mix: if the original mix is x%, then (x+60)/2=72, so x=84%. Now the original mix (A:B=1:3) averaging to 84% with A at 60% gives (60+3b)/4=84, so b=92%.', NULL, 6, 'medium', 'medium', 90, 'Treating ''doubling the volume by adding A'' as adding A in the original 1:3 ratio instead of a fresh 1:1 mix.'),
  ('CAT2020_QA_S3_2', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'MIX_ALLIGATION', 'A batsman played n + 2 innings and got out on all occasions. His average score in these n + 2 innings was 29 runs and he scored 38 and 15 runs in the last two innings. The batsman scored less than 38 runs in each of the first n innings. In these n innings, his average score was 30 runs and lowest score was x runs. The smallest possible value of x is', 'mcq', '4', '3', '2', '1', 'c', 'Total of all n+2 innings = 29(n+2). Subtracting the last two innings (38+15=53), total of first n innings = 29n+5. This also equals 30n (given average). Solving, n=5, so the first-5-innings total is 150. To make x as small as possible, the other four scores should be as large as possible while staying under 38, i.e. 37 each. Then 4(37)+x=150, giving x=2.', NULL, 7, 'medium', 'high', 120, 'Forgetting the constraint that each of the first n scores must be strictly less than 38 while maximizing the other scores.'),
  ('CAT2020_QA_S3_3', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'ALG_QUAD_ROOT', 'Let m and n be positive integers. If x^2 + mx + 2n = 0 and x^2 + 2nx + m = 0 have real roots, then the smallest possible value of m + n is', 'mcq', '7', '6', '8', '5', 'b', 'Both quadratics need non-negative discriminant: m^2 - 8n >= 0 and 4n^2 - 4m >= 0, i.e. m^2 >= 8n and n^2 >= m. Testing small positive integers, m=4, n=2 satisfies both (16>=16 and 4>=4), giving the smallest m+n=6.', NULL, 7, 'medium', 'high', 120, 'Checking only one of the two discriminant conditions instead of satisfying both simultaneously.'),
  ('CAT2020_QA_S3_4', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'TW_COMBINED', 'A contractor agreed to construct a 6 km road in 200 days. He employed 140 persons for the work. After 60 days, he realized that only 1.5 km road has been completed. How many additional people would he need to employ in order to finish the work exactly on time?', 'tita', NULL, NULL, NULL, NULL, '40', 'Measure the job in person-days. In 60 days, 140 people finished 1.5 km, so 1.5 km costs 140 × 60 = 8400 person-days, i.e. 5600 person-days per km. The remaining 6 − 1.5 = 4.5 km therefore needs 4.5 × 5600 = 25200 person-days, and only 200 − 60 = 140 days are left. Required workforce = 25200/140 = 180, so he must hire 180 − 140 = 40 more people.', NULL, 7, 'high', 'medium', 150, 'Continuing with the originally planned efficiency instead of recalibrating based on the actual work done in the first 60 days.'),
  ('CAT2020_QA_S3_5', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'ALG_RECURRENCE', 'If x1 = -1 and xm = x(m+1) + (m + 1) for every positive integer m, then X100 equals', 'mcq', '-5050', '-5151', '-5051', '-5150', 'a', 'Rearrange to x(m+1) = xm − (m+1). Starting from x1 = −1: x2 = −1 − 2 = −3, x3 = −3 − 3 = −6, x4 = −6 − 4 = −10. In general xn = −(1 + 2 + ⋯ + n) = −n(n+1)/2. So x100 = −100 × 101/2 = −5050.', NULL, 6, 'medium', 'medium', 100, 'Getting the direction of the recurrence backwards, e.g. writing x(m+1) = xm + (m+1) instead of subtracting.'),
  ('CAT2020_QA_S3_6', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'ALG_LOG_EQ', 'If log_a 30 = A, log_a(5/3) = -B and log_2 a = 1/3, then log_3 a equals', 'mcq', '2/(A+B-3)', '2/(A+B)-3', '(A+B)/2-3', '(A+B-3)/2', 'a', 'log_a 30 = log_a 5 + log_a 2 + log_a 3 = A, and log_a(5/3) = log_a 5 - log_a 3 = -B, i.e. log_a 3 - log_a 5 = B. Since log_2 a = 1/3, a = 2^(1/3), so log_a 2 = 3. Substituting into the first equation gives log_a 5 + log_a 3 = A-3. Adding this to log_a 3 - log_a 5 = B gives 2 log_a 3 = A+B-3, so log_a 3 = (A+B-3)/2, and log_3 a = 2/(A+B-3).', NULL, 8, 'high', 'high', 150, 'Sign errors while combining the two given log relations, especially with the -B term.'),
  ('CAT2020_QA_S3_7', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'ALG_LINEAR_WORD', 'Dick is thrice as old as Tom and Harry is twice as old as Dick. If Dick''s age is 1 year less than the average age of all three, then Harry''s age, in years, is', 'tita', NULL, NULL, NULL, NULL, '18', 'Let Tom = x, so Dick = 3x and Harry = 6x. Dick''s age is 1 less than the average: 3x+1 = (x+3x+6x)/3 = 10x/3. Solving gives x=3, so Harry = 6(3) = 18.', NULL, 4, 'low', 'low', 90, 'Setting up the average of the three ages incorrectly, e.g. dividing by 2 instead of 3.'),
  ('CAT2020_QA_S3_8', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'TSD_BASIC', 'Vimla starts for office every day at 9 am and reaches exactly on time if she drives at her usual speed of 40 km/hr. She is late by 6 minutes if she drives at 35 km/hr. One day, she covers two-thirds of her distance to office in one-thirds of her usual total time to reach office, and then stops for 8 minutes. The speed, in km/hr, at which she should drive the remaining distance to reach office exactly on time is', 'mcq', '29', '26', '28', '27', 'c', 'From the two speed scenarios, d/35 - d/40 = 6/60, giving d = 28 km, and usual time = 28/40 hr = 42 min. In one-third of this time (14 min) she covers two-thirds of the distance, then stops 8 min, using 22 min total. She must cover the remaining one-third distance (28/3 km) in the remaining 20 min, requiring a speed of (28/3)/(20/60) = 28 km/hr.', NULL, 7, 'high', 'medium', 150, 'Forgetting to subtract the 8-minute stop from the remaining time before calculating the required speed.'),
  ('CAT2020_QA_S3_9', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'NS_INTEGER', 'Let m and n be natural numbers such that n is even and 0.2 < m/20, n/m, n/11 < 0.5. Then m - 2n equals', 'mcq', '3', '1', '2', '4', 'b', 'Take the constraints one at a time. From 0.2 < n/11 < 0.5, n lies strictly between 2.2 and 5.5, and n is even, so n = 4. From 0.2 < m/20 < 0.5, m lies strictly between 4 and 10. From 0.2 < n/m < 0.5 with n = 4: 0.2 < 4/m gives m < 20, and 4/m < 0.5 gives m > 8. Intersecting with 4 < m < 10 leaves m = 9. So m − 2n = 9 − 8 = 1.', NULL, 7, 'medium', 'high', 150, 'Applying only one or two of the three given inequality constraints instead of all three together.'),
  ('CAT2020_QA_S3_10', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'MOD_COUNT', 'How many integers in the set {100, 101, 102, ..., 999} have at least one digit repeated?', 'tita', NULL, NULL, NULL, NULL, '252', 'Total 3-digit numbers = 900. Numbers with all distinct digits: hundreds digit has 9 choices (1-9), tens digit 9 remaining choices (including 0), units digit 8 remaining choices, giving 9x9x8=648. Numbers with at least one repeated digit = 900 - 648 = 252.', NULL, 5, 'medium', 'medium', 90, 'Allowing 0 as a valid choice for the hundreds digit while counting the no-repeat numbers.'),
  ('CAT2020_QA_S3_11', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'PERC_BASIC', 'In the final examination, Bishnu scored 52% and Asha scored 64%. The marks obtained by Bishnu is 23 less, and that by Asha is 34 more than the marks obtained by Ramesh. The marks obtained by Geeta, who scored 84%, is', 'mcq', '357', '417', '439', '399', 'd', 'Let total marks = 100x. Bishnu''s marks = 52x = Ramesh - 23, so Ramesh = 52x+23. Asha''s marks = 64x = Ramesh + 34, so Ramesh = 64x-34. Equating: 52x+23 = 64x-34, giving x = 19/4. Geeta''s marks = 84x = 84(19/4) = 399.', NULL, 6, 'medium', 'medium', 120, 'Reversing which relation (''23 less'' vs ''34 more'') applies to Bishnu versus Asha relative to Ramesh.'),
  ('CAT2020_QA_S3_12', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'ALG_LOG', 'If a,b,c are non-zero and 14^a = 36^b = 84^c, then 6b(1/c - 1/a) is equal to', 'tita', NULL, NULL, NULL, NULL, '3', 'Let the common value be k, so a = log_14 k, b = log_36 k, c = log_84 k. Then 1/c - 1/a = log_k 84 - log_k 14 = log_k(84/14) = log_k 6. So 6b(1/c-1/a) = 6 log_36 k times log_k 6 = 6 log_36 6. Since 36 = 6^2, log_36 6 = 1/2, giving 6(1/2) = 3.', NULL, 8, 'high', 'high', 150, 'Not simplifying log_36 6 to 1/2 correctly, or mishandling the base-change while combining the log terms.'),
  ('CAT2020_QA_S3_13', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'CI_HALF', 'A person invested a certain amount of money at 10% annual interest, compounded half-yearly. After one and a half years, the interest and principal together became Rs.18522. The amount, in rupees, that the person had invested is', 'tita', NULL, NULL, NULL, NULL, '16000', 'Compounded half-yearly at 10% annual means 5% per half-year, over 3 half-year periods. So P(1.05)^3 = 18522, giving P = 16000.', NULL, 5, 'medium', 'low', 90, 'Using 10% as the half-yearly rate instead of correctly halving it to 5%.'),
  ('CAT2020_QA_S3_14', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'PL_CP_SP', 'A man buys 35 kg of sugar and sets a marked price in order to make a 20% profit. He sells 5 kg at this price, and 15 kg at a 10% discount. Accidentally, 3 kg of sugar is wasted. He sells the remaining sugar by raising the marked price by p percent so as to make an overall profit of 15%. Then p is nearest to', 'mcq', '22', '35', '25', '31', 'c', 'Taking CP per kg as 100, total CP = 3500 and marked price per kg = 120. Target overall SP for 15% profit = 3500(1.15) = 4025. SP from first 5 kg = 5(120) = 600, from next 15 kg at 10% off = 15(120)(0.9) = 1620. The remaining 12 kg (after 3 kg wasted) must fetch 4025-600-1620=1805, i.e. about 150.4 per kg. This is a markup of about (150.4-120)/120 x 100 ≈ 25% over the marked price.', NULL, 8, 'high', 'medium', 150, 'Computing the markup percentage p relative to the cost price instead of relative to the already-marked-up price.'),
  ('CAT2020_QA_S3_15', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'GEO_LINE', 'The points (2,1) and (-3,-4) are opposite vertices of a parallelogram. If the other two vertices lie on the line x + 9y + c = 0, then c is', 'mcq', '12', '13', '15', '14', 'd', 'The diagonals of a parallelogram bisect each other, so both pairs of opposite vertices share the same midpoint. The midpoint of (2,1) and (-3,-4) is (-1/2, -3/2), which must also be the midpoint of the other diagonal and therefore lies on the given line. Substituting: -1/2 + 9(-3/2) + c = 0, giving c = 14.', NULL, 7, 'medium', 'high', 120, 'Not recognizing that the midpoint of both diagonals must coincide, and instead trying to locate the individual vertices.'),
  ('CAT2020_QA_S3_16', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'TSD_TRAIN', 'A and B are two railway stations 90 km apart. A train leaves A at 9:00 am, heading towards B at a speed of 40 km/hr. Another train leaves B at 10:30 am, heading towards A at a speed of 20 km/hr. The trains meet each other at', 'mcq', '11:45 am', '11:20 am', '11:00 am', '10:45 am', 'c', 'By 10:30 am, the first train has covered 1.5(40)=60 km, leaving a 30 km gap. From 10:30 am, the trains close this gap at a combined speed of 60 km/hr, taking 30/60 = 0.5 hr, so they meet at 11:00 am.', NULL, 5, 'low', 'low', 90, 'Forgetting to account for the head-start distance covered by the first train before the second train departs.'),
  ('CAT2020_QA_S3_17', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'NS_INTEGER', 'Let N, x and y be positive integers such that N = x + y, 2 < x < 10 and 14 < y < 23. If N > 25, then how many distinct values are possible for N?', 'tita', NULL, NULL, NULL, NULL, '6', 'The integer ranges are 3 ≤ x ≤ 9 and 15 ≤ y ≤ 22, so N = x + y runs from 3 + 15 = 18 up to 9 + 22 = 31, and every value in between is achievable. Restricting to N > 25 leaves N = 26, 27, 28, 29, 30, 31 — 6 distinct values.', NULL, 7, 'medium', 'high', 150, 'Assuming every integer N in the theoretical range 25 to 31 is achievable without checking that each is reachable by some valid (x,y) pair.'),
  ('CAT2020_QA_S3_18', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'ALG_LINEAR_2', 'Let k be a constant. The equations kx + y = 3 and 4x + ky = 4 have a unique solution if and only if', 'mcq', '|k| ≠ 2', '|k| = 2', 'k ≠ 2', 'k = 2', 'a', 'A unique solution requires the coefficient ratios to differ: k/4 ≠ 1/k, i.e. k^2 ≠ 4, i.e. |k| ≠ 2.', NULL, 5, 'low', 'medium', 90, 'Confusing the condition for a unique solution with the condition for no solution or infinite solutions.'),
  ('CAT2020_QA_S3_19', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'SET_IEP', 'How many of the integers 1, 2, ..., 120, are divisible by none of 2, 5 and 7?', 'mcq', '42', '41', '40', '43', 'b', 'Using inclusion-exclusion: multiples of 2=60, of 5=24, of 7=17, of 2&5=12, of 2&7=8, of 5&7=3, of 2&5&7=1. Union = 60+24+17-12-8-3+1 = 79. None of these = 120-79 = 41.', NULL, 6, 'medium', 'medium', 120, 'Forgetting to add back the triple-overlap term when applying inclusion-exclusion.'),
  ('CAT2020_QA_S3_20', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'NS_FACTORS', 'How many pairs (a, b) of positive integers are there such that a ≤ b and ab = 4^2017?', 'mcq', '2018', '2019', '2017', '2020', 'a', '4^2017 = 2^4034, which has 4035 divisors. Since 4^2017 is a perfect square, the pairs with a ≤ b number (4035+1)/2 = 2018.', NULL, 6, 'medium', 'medium', 120, 'Forgetting to add 1 for the a=b case when halving the total divisor count for a perfect square.'),
  ('CAT2020_QA_S3_21', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'TSD_CIRCULAR', 'Anil, Sunil, and Ravi run along a circular path of length 3 km, starting from the same point at the same time, and going in the clockwise direction. If they run at speeds of 15 km/hr, 10 km/hr, and 8 km/hr, respectively, how much distance in km will Ravi have run when Anil and Sunil meet again for the first time at the starting point?', 'mcq', '4.8', '4.6', '5.2', '4.2', 'a', 'Anil completes a lap in 3/15 hr = 12 min, Sunil in 3/10 hr = 18 min. Both are back at the starting point together after LCM(12,18) = 36 min = 3/5 hr. In that time, Ravi covers 8(3/5) = 4.8 km.', NULL, 6, 'medium', 'medium', 120, 'Taking the LCM of the speeds instead of the LCM of the actual lap times.'),
  ('CAT2020_QA_S3_22', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'GEO_TRAP', 'In a trapezium ABCD, AB is parallel to DC, BC is perpendicular to DC and ∠BAD = 45°. If DC = 5cm, BC = 4 cm, the area of the trapezium in sq cm is', 'tita', NULL, NULL, NULL, NULL, '28', 'Drop a perpendicular from D to AB, meeting it at E. Since BC ⊥ DC and AB ∥ DC, BCDE is a rectangle, so DE = BC = 4 and EB = DC = 5. In right triangle AED with ∠A = 45°, AE = DE = 4, so AB = AE+EB = 9. Area = (1/2)(AB+DC)(height) = (1/2)(9+5)(4) = 28.', NULL, 6, 'medium', 'medium', 120, 'Not recognizing that BCDE forms a rectangle, which is what gives EB = DC.'),
  ('CAT2020_QA_S3_23', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'GEO_LINE', 'The area, in sq. units, enclosed by the lines x = 2, y = |x - 2| + 4, the X-axis and the Y-axis is equal to', 'mcq', '10', '6', '8', '12', 'a', 'The bounded region is a trapezium with vertices (0,0), (2,0), (2,4), (0,6). The two parallel sides measure 6 (at x=0) and 4 (at x=2), with height 2 between them. Area = (1/2)(6+4)(2) = 10.', NULL, 6, 'medium', 'medium', 120, 'Misidentifying the vertices of the enclosed region, especially the y-intercept of the line y=|x-2|+4.'),
  ('CAT2020_QA_S3_24', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'ALG_EXP', 'If f(x + y) = f(x)f(y) and f(5) = 4, then f(10) - f(-10) is equal to', 'mcq', '14.0625', '0', '15.9375', '3', 'c', 'The functional equation implies f(x) = a^x for some base a, with a^5 = 4, so a = 4^(1/5). Then f(10) = a^10 = (4^(1/5))^10 = 4^2 = 16, and f(-10) = 1/a^10 = 1/16. So f(10)-f(-10) = 16 - 1/16 = 15.9375.', NULL, 6, 'medium', 'medium', 120, 'Computing f(-10) as -f(10) instead of correctly as the reciprocal 1/f(10).'),
  ('CAT2020_QA_S3_25', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'ALG_LOG', '(2 x 4 x 8 x 16) / [(log_2 4)^2 (log_4 8)^3 (log_8 16)^4] equals', 'tita', NULL, NULL, NULL, NULL, '24', 'Evaluate the logs: log₂4 = 2, log₄8 = 3/2, log₈16 = 4/3. Denominator = 2² × (3/2)³ × (4/3)⁴ = 4 × 27/8 × 256/81 = 128/3. Numerator = 2 × 4 × 8 × 16 = 1024. So the expression = 1024 ÷ (128/3) = 1024 × 3/128 = 24.', NULL, 7, 'high', 'medium', 150, 'Arithmetic slips while simplifying the fractional log values raised to different powers.'),
  ('CAT2020_QA_S3_26', 2020, 'Slot 3', 'CAT 2020 Slot 3 (Cracku PYQ compilation)', TRUE, 'GEO_COORD_CIRCLE', 'The vertices of a triangle are (0,0), (4,0) and (3,9). The area of the circle passing through these three points is', 'mcq', '14π/3', '123π/7', '12π/5', '205π/9', 'd', 'Using the general circle equation x^2+y^2+2gx+2fy+c=0 and substituting the three points: (0,0) gives c=0; (4,0) gives g=-2; (3,9) gives f=-13/3. The radius squared is g^2+f^2-c = 4+169/9 = 205/9, so the area is 205π/9.', NULL, 7, 'high', 'medium', 150, 'Sign or arithmetic errors while substituting the third point''s coordinates into the circle equation.'),
  ('CAT2020_QA_S2_1', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'TSD_BASIC', 'The distance from B to C is thrice that from A to B. Two trains travel from A to C via B. The speed of train 2 is double that of train 1 while traveling from A to B and their speeds are interchanged while traveling from B to C. The ratio of the time taken by train 1 to that taken by train 2 in travelling from A to C is', 'mcq', '5:7', '4:1', '1:4', '7:5', 'a', 'Let AB=x, BC=3x, and train 1''s AB speed be v (so train 2''s AB speed is 2v). On BC the speeds swap: train 1 goes at 2v, train 2 at v. Time1 = x/v + 3x/(2v) = 5x/(2v). Time2 = x/(2v) + 3x/v = 7x/(2v). Ratio = 5:7.', NULL, 6, 'medium', 'medium', 120, 'Forgetting that the speeds swap for the second leg of the journey (B to C).'),
  ('CAT2020_QA_S2_2', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'TW_COMBINED', 'John takes twice as much time as Jack to finish a job. Jack and Jim together take one-thirds of the time to finish the job than John takes working alone. Moreover, in order to finish the job, John takes three days more than that taken by three of them working together. In how many days will Jim finish the job working alone?', 'tita', NULL, NULL, NULL, NULL, '4', 'Let Jack take t days (John takes 2t). Jack+Jim''s combined rate is 1/(2t/3) = 3/(2t); subtracting Jack''s rate 1/t gives Jim''s rate = 1/(2t), so Jim alone takes 2t days. All three together have rate 1/t+1/(2t)+1/(2t)=2/t, taking t/2 days. Since John (2t days) takes 3 more days than the trio (t/2 days): 2t = t/2+3, giving t=2. So Jim takes 2t=4 days.', NULL, 8, 'high', 'high', 180, 'Mixing up rates and times when combining Jack and Jim''s given fraction of John''s time.'),
  ('CAT2020_QA_S2_3', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'ALG_INEQ_QUAD', 'Let f(x) = x^2 + ax + b and g(x) = f(x+1) - f(x-1). If f(x) >= 0 for all real x, and g(20) = 72, then the smallest possible value of b is', 'mcq', '16', '4', '1', '0', 'b', 'g(x) = f(x+1)-f(x-1) simplifies to 4x+2a, so g(20)=80+2a=72 gives a=-4, and f(x)=x^2-4x+b. For f(x) >= 0 for all x, the discriminant must satisfy 16-4b <= 0, i.e. b >= 4. The smallest such b is 4.', NULL, 6, 'medium', 'medium', 120, 'Using a strict discriminant inequality (<0) instead of the correct non-strict condition (<=0) for ''always non-negative''.'),
  ('CAT2020_QA_S2_4', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'CI_ANNUAL', 'For the same principal amount, the compound interest for two years at 5% per annum exceeds the simple interest for three years at 3% per annum by Rs 1125. Then the principal amount in rupees is', 'tita', NULL, NULL, NULL, NULL, '90000', 'CI for 2 years at 5% = P[(1.05)^2 - 1] = 0.1025P. SI for 3 years at 3% = 0.09P. The difference 0.1025P - 0.09P = 0.0125P = 1125, giving P = 90000.', NULL, 6, 'medium', 'medium', 120, 'Approximating 2-year compound interest as simply 2x5%=10% instead of properly compounding.'),
  ('CAT2020_QA_S2_5', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'GEO_CIRCLE_CHORD', 'Let C be a circle of radius 5 meters having center at O. Let PQ be a chord of C that passes through points A and B where A is located 4 meters north of O and B is located 3 meters east of O. Then, the length of PQ, in meters, is nearest to', 'mcq', '8.8', '7.8', '6.6', '7.2', 'a', 'Put O at the origin, so A = (0, 4) and B = (3, 0). The chord lies along the line through these two points: x/3 + y/4 = 1, i.e. 4x + 3y = 12. The perpendicular distance from O to this line is |0 + 0 − 12|/√(4² + 3²) = 12/5 = 2.4. For a chord at distance d from the centre of a circle of radius r, half the chord is √(r² − d²) = √(25 − 5.76) = √19.24 ≈ 4.386. So PQ ≈ 8.77, nearest to 8.8.', NULL, 9, 'high', 'high', 180, 'Assuming the chord passes through the center, or misplacing the foot of the perpendicular from O.'),
  ('CAT2020_QA_S2_6', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'TSD_RELATIVE', 'In a car race, car A beats car B by 45 km. car B beats car C by 50 km. and car A beats car C by 90 km. The distance (in km) over which the race has been conducted is', 'mcq', '475', '450', '500', '550', 'b', 'Let the race distance be m km. The speed ratios give v_A/v_B = m/(m-45) and v_B/v_C = m/(m-50), and their product must equal v_A/v_C = m/(m-90). Setting up and solving this equation gives m = 450.', NULL, 8, 'high', 'high', 150, 'Simply adding the given ''beats by'' distances instead of relating them through speed ratios.'),
  ('CAT2020_QA_S2_7', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'MOD_LINEAR', 'How many 4-digit numbers, each greater than 1000 and each having all four digits distinct, are there with 7 coming before 3?', 'tita', NULL, NULL, NULL, NULL, '315', 'Case 1: 7 is the leading digit. The remaining 3 positions can be filled with 3, and two other distinct digits from the remaining 8, giving 3x8x7=168 arrangements. Case 2: 7 is not the leading digit (so the leading digit can''t be 0). Careful counting of valid arrangements where 7 still precedes 3 gives 147. Total = 168+147 = 315.', NULL, 8, 'high', 'high', 180, 'Forgetting that the leading digit cannot be 0 in the case where 7 is not in the leading position.'),
  ('CAT2020_QA_S2_8', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'GEO_MENS_2D', 'The sum of the perimeters of an equilateral triangle and a rectangle is 90cm. The area, T, of the triangle and the area, R, of the rectangle, both in sq cm, satisfying the relationship R = T^2. If the sides of the rectangle are in the ratio 1:3, then the length, in cm, of the longer side of the rectangle, is', 'mcq', '27', '21', '24', '18', 'a', 'Let the triangle''s side be m (perimeter 3m) and rectangle sides a, 3a (perimeter 8a), so 3m+8a=90. T=(√3/4)m^2 and R=3a^2. From R=T^2, 3a^2=(3/16)m^4, giving a=m^2/4. Substituting into 3m+8a=90 gives 2m^2+3m-90=0, whose positive root is m=6, so a=9 and the longer side 3a=27.', NULL, 8, 'high', 'high', 180, 'Discarding or mishandling the negative root of the resulting quadratic instead of taking only the positive, valid one.'),
  ('CAT2020_QA_S2_9', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'RATIO_BASIC', 'A sum of money is split among Amal, Sunil and Mita so that the ratio of the shares of Amal and Sunil is 3:2, while the ratio of the shares of Sunil and Mita is 4:5. If the difference between the largest and the smallest of these three shares is Rs.400, then Sunil''s share, in rupees, is', 'tita', NULL, NULL, NULL, NULL, '800', 'Combining the two ratios on a common scale for Sunil gives Amal:Sunil:Mita = 6:4:5. The largest share is 6x (Amal) and smallest is 4x (Sunil), so 2x=400, x=200. Sunil''s share = 4x = 800.', NULL, 5, 'low', 'medium', 120, 'Comparing the two given ratios without first scaling them to a common term (Sunil''s share).'),
  ('CAT2020_QA_S2_10', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'ALG_LOG', 'The value of log_a(a/b) + log_b(b/a), for 1 < a ≤ b cannot be equal to', 'mcq', '0', '-1', '1', '-0.5', 'c', 'The expression simplifies to 2 - (log_a b + 1/log_a b). Since a ≤ b and both exceed 1, log_a b >= 1, so by AM-GM, log_a b + 1/log_a b >= 2, making the whole expression always <= 0. Hence a positive value like 1 is never possible.', NULL, 7, 'medium', 'high', 120, 'Not applying AM-GM to establish that the bracketed term is always at least 2, and hence missing the sign bound.'),
  ('CAT2020_QA_S2_11', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'SET_VENN', 'Students in a college have to choose at least two subjects from chemistry, mathematics and physics. The number of students choosing all three subjects is 18, choosing mathematics as one of their subjects is 23 and choosing physics as one of their subjects is 25. The smallest possible number of students who could choose chemistry as one of their subjects is', 'mcq', '22', '21', '20', '19', 'c', 'Math total: (math&chem only)+(math&phys only)+18=23, so these two overlaps sum to 5. Physics total similarly gives (phys&chem only)+(math&phys only)+18=25, so those two sum to 7. To minimize chemistry''s total, maximize the math&phys-only overlap (up to 5, making math&chem only = 0), leaving phys&chem only = 7-5=2. Chemistry total = 0+2+18 = 20.', NULL, 7, 'medium', 'high', 150, 'Not recognizing that maximizing the ''math and physics only'' overlap is what minimizes chemistry''s count.'),
  ('CAT2020_QA_S2_12', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'MIX_ALLIGATION', 'In a group of 10 students, the mean of the lowest 9 scores is 42 while the mean of the highest 9 scores is 47. For the entire group of 10 students, the maximum possible mean exceeds the minimum possible mean by', 'mcq', '5', '4', '3', '6', 'b', 'Sum of any 9 lowest scores = 378, sum of any 9 highest = 423. The minimum overall mean occurs when the 10th (highest) value is as small as possible, i.e. 47, giving total 425 and mean 42.5. The maximum overall mean occurs when the 1st (lowest) value is as large as possible, i.e. 42, giving total 465 and mean 46.5. The difference is 4.', NULL, 8, 'high', 'high', 180, 'Not correctly bounding the extreme (10th or 1st) value using the two given sub-group means.'),
  ('CAT2020_QA_S2_13', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'TSD_RELATIVE', 'A and B are two points on a straight line. Ram runs from A to B while Rahim runs from B to A. After crossing each other. Ram and Rahim reach their destination in one minute and four minutes, respectively. if they start at the same time, then the ratio of Ram''s speed to Rahim''s speed is', 'mcq', '1/2', '√2', '2', '2√2', 'c', 'For two objects starting simultaneously from opposite ends and crossing, the ratio of their speeds equals the square root of the ratio of their post-crossing travel times (inverted): speed ratio = √(4/1) = 2.', NULL, 6, 'medium', 'medium', 120, 'Using the ratio of the post-crossing times directly as the speed ratio instead of taking the square root.'),
  ('CAT2020_QA_S2_14', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'TSD_CIRCULAR', 'Two circular tracks T1 and T2 of radii 100 m and 20 m, respectively touch at a point A. Starting from A at the same time, Ram and Rahim are walking on track T1 and track T2 at speeds 15 km/hr and 5 km/hr respectively. The number of full rounds that Ram will make before he meets Rahim again for the first time is', 'mcq', '5', '3', '2', '4', 'b', 'Circumference of T1 = 2π(100) = 200π m, of T2 = 2π(20) = 40π m. Converting speeds to m/hr: Ram 15000, Rahim 5000. Lap times: Ram π/75 hr, Rahim π/125 hr. They are both back at A together at the LCM of these times = π/HCF(75, 125) = π/25 hr. In that time Ram completes (π/25) ÷ (π/75) = 3 full rounds (and Rahim completes 5).', NULL, 8, 'high', 'high', 180, 'Computing the meeting time using the ratio of the radii alone instead of the actual lap times (which also depend on speed).'),
  ('CAT2020_QA_S2_15', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'GEO_CIRCLE_TANGENT', 'Let C1 and C2 be concentric circles such that the diameter of C1 is 2cm longer than that of C2. If a chord of C1 has length 6cm and is a tangent to C2, then the diameter, in cm, of C1 is', 'tita', NULL, NULL, NULL, NULL, '10', 'Let C2''s radius be r, so C1''s radius is r+1. The chord of C1, tangent to C2, is bisected by the perpendicular from the center, giving a right triangle: r^2+3^2=(r+1)^2. Solving gives r=4, so C1''s diameter = 2(r+1) = 10.', NULL, 6, 'medium', 'medium', 120, 'Building the right triangle using C1''s radius as the tangent-line leg instead of C2''s radius.'),
  ('CAT2020_QA_S2_16', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'PL_SUCCESSIVE_DISCOUNT', 'Anil buys 12 toys and labels each with the same selling price. He sells 8 toys initially at 20% discount on the labeled price. Then he sells the remaining 4 toys at an additional 25% discount on the discounted price. Thus, he gets a total of Rs 2112, and makes a 10% profit. With no discounts, his percentage of profit would have been', 'mcq', '50', '60', '54', '55', 'a', 'Total CP = 12x; with 10% profit, total SP = 13.2x = 2112, so x = 160 (CP per toy). Let M be the labeled price per toy: 8(0.8M) + 4(0.8)(0.75)M = 8.8M = 2112, giving M=240. Without discounts, profit% = (240-160)/160 x 100 = 50%.', NULL, 8, 'high', 'medium', 180, 'Applying the second 25% discount to the original labeled price instead of to the already-discounted price.'),
  ('CAT2020_QA_S2_17', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'ALG_EXP', 'The number of integers that satisfy the equality (x^2 - 5x + 7)^(x+1) = 1 is', 'mcq', '3', '2', '4', '5', 'a', 'This holds if the base equals 1 (x^2-5x+6=0, giving x=2,3), if the exponent is 0 with a non-zero base (x=-1), or if the base is -1 with an even exponent (x^2-5x+7=-1 has no real solutions here). Combining the valid cases gives 3 integer solutions: x=2, 3, -1.', NULL, 7, 'medium', 'high', 120, 'Overlooking the base=-1-with-even-exponent case entirely, even when it turns out to contribute no solutions.'),
  ('CAT2020_QA_S2_18', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'NS_INTEGER', 'The number of pairs of integers (x, y) satisfying x ≥ y ≥ -20 and 2x + 5y = 99', 'tita', NULL, NULL, NULL, NULL, '17', 'x = (99-5y)/2, which is an integer only when y is odd. The condition x >= y gives 99 >= 7y, i.e. y <= 14 (approx). Combined with y >= -20, the valid odd values of y from -20 to 14 number 17.', NULL, 6, 'medium', 'medium', 120, 'Forgetting the parity constraint that y must be odd for x to come out as an integer.'),
  ('CAT2020_QA_S2_19', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'GEO_TRI_SPECIAL', 'From an interior point of an equilateral triangle, perpendiculars are drawn on all three sides. The sum of the lengths of the three perpendiculars is s. Then the area of the triangle is', 'mcq', '√3s^2/2', '2s^2/√3', 's^2/(2√3)', 's^2/√3', 'd', 'By Viviani''s theorem, the sum of the perpendicular distances from any interior point to the three sides of an equilateral triangle equals the triangle''s height, so (√3/2)a = s, giving a = 2s/√3. The area (√3/4)a^2 then simplifies to s^2/√3.', NULL, 6, 'medium', 'medium', 120, 'Misremembering or misapplying Viviani''s theorem''s coefficient when relating s to the side length.'),
  ('CAT2020_QA_S2_20', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'ALG_GP', 'Let the m-th and n-th terms of a geometric progression be 3/4 and 12. respectively, where m < n. If the common ratio of the progression is an integer r, then the smallest possible value of r + n - m is', 'mcq', '6', '2', '-4', '-2', 'd', 'The ratio of terms gives r^(n-m) = 12/(3/4) = 16. Testing integer values of r (including negative ones, since even powers of negative integers are also positive) that satisfy r^(n-m)=16, the combination r=-4, n-m=2 works, giving r+n-m = -4+2 = -2, which is the smallest among the valid options.', NULL, 7, 'medium', 'high', 150, 'Only testing positive integer values of r and missing that negative integers can also satisfy the equation via even powers.'),
  ('CAT2020_QA_S2_21', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'PERC_SUCCESSIVE', 'In May, John bought the same amount of rice and the same amount of wheat as he had bought in April, but spent ₹ 150 more due to price increase of rice and wheat by 20% and 12%, respectively. If John had spent ₹ 450 on rice in April, then how much did he spend on wheat in May?', 'mcq', 'Rs.560', 'Rs.570', 'Rs.590', 'Rs.580', 'a', 'The extra amount spent on rice = 20% of 450 = 90. So the extra spent on wheat = 150-90 = 60, which is 12% of the April wheat spend, giving April wheat spend = 500. May wheat spend = 500 x 1.12 = 560.', NULL, 5, 'low', 'low', 120, 'Trying to compute the May wheat spend directly from the total 150 extra without first isolating the rice portion.'),
  ('CAT2020_QA_S2_22', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'NS_INTEGER', 'If x and y are non-negative integers such that x + 9 = z, y + 1 = z and x + y < z + 5, then the maximum possible value of 2x + y equals', 'tita', NULL, NULL, NULL, NULL, '23', 'With x=z-9 and y=z-1, the constraint x+y<z+5 becomes (z-9)+(z-1)<z+5, i.e. z<15, so z<=14 (also z>=9 for x to be non-negative). At z=14, x=5 and y=13, giving 2x+y=10+13=23.', NULL, 6, 'medium', 'medium', 120, 'Forgetting the non-negativity constraint on x, which requires z to be at least 9.'),
  ('CAT2020_QA_S2_23', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'ALG_LINEAR_WORD', 'Aron bought some pencils and sharpeners. Spending the same amount of money as Aron, Aditya bought twice as many pencils and 10 less sharpeners. If the cost of one sharpener is ₹ 2 more than the cost of a pencil, then the minimum possible number of pencils bought by Aron and Aditya together is', 'mcq', '33', '27', '30', '36', 'a', 'Let Aron buy p pencils and s sharpeners at price a and a+2 respectively. Equating the two spends and simplifying gives pa=10(a+2), so a=20/(p-10). For a to be a positive integer, the smallest valid p greater than 10 is p=11, giving a=20. Total pencils bought = p+2p = 3p = 33.', NULL, 8, 'high', 'high', 180, 'Not searching for the smallest p that simultaneously satisfies p>10 and yields an integer value for a.'),
  ('CAT2020_QA_S2_24', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'ALG_FUNC_OPT', 'For real x, the maximum possible value of x/√(1+x^4) is', 'mcq', '1/2', '1', '1/√3', '1/√2', 'd', 'Let y = x/√(1+x^4). Then y^2 = 1/(1/x^2 + x^2). By AM-GM, 1/x^2 + x^2 >= 2, so y^2 <= 1/2, giving y <= 1/√2.', NULL, 6, 'medium', 'medium', 120, 'Missing the AM-GM equality condition (x^2=1) needed to confirm the bound is actually achieved.'),
  ('CAT2020_QA_S2_25', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'ALG_INEQ_MOD', 'In how many ways can a pair of integers (x , a) be chosen such that x^2 - 2|x| + |a - 2| = 0?', 'mcq', '6', '5', '4', '7', 'd', 'Splitting into cases based on the sign of x (and correspondingly solving for a as a function of x, then checking which give integer, valid pairs) across both x>=0 and x<0 branches yields 7 valid integer pairs (x,a) in total.', NULL, 8, 'high', 'high', 180, 'Not splitting the |x| term into both sign cases, which undercounts the valid integer pairs.'),
  ('CAT2020_QA_S2_26', 2020, 'Slot 2', 'CAT 2020 Slot 2 (Cracku PYQ compilation)', TRUE, 'ALG_FUNC_OPT', 'if x and y are positive real numbers satisfying x + y = 102, then the minimum possible value of 2601(1 + 1/x)(1 + 1/y) is', 'tita', NULL, NULL, NULL, NULL, '2704', 'Expanding, the expression equals 2601 x (xy+x+y+1)/xy = 2601 x (103/xy + 1). Since this is minimized when xy is as large as possible, and by AM-GM xy is maximized at x=y=51 giving xy=2601, substituting gives 2601 x (103/2601+1) = 103+2601 = 2704.', NULL, 7, 'medium', 'high', 150, 'Minimizing xy instead of maximizing it, due to not tracking the sign of xy''s coefficient in the simplified expression.'),
  ('CAT2020_QA_S1_1', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'ALG_LOG', 'If Y is a negative number such that 2^(Y^2(log_3 5)) = 5^(log_2 3), then Y equals to:', 'mcq', 'log_2(1/5)', 'log_2(1/3)', '-log_2(1/5)', '-log_2(1/3)', 'b', 'Rewriting both sides with a common base and simplifying the exponents leads to Y^2 (log_3 2) = log_2 3, so Y^2 = (log_2 3)^2, giving Y = ±log_2 3. Since Y must be negative, Y = -log_2 3 = log_2(1/3).', NULL, 8, 'high', 'high', 150, 'Taking the positive root of Y^2 despite the problem specifying that Y is negative.'),
  ('CAT2020_QA_S1_2', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'ALG_RECURRENCE', 'A gentleman decided to treat a few children in the following manner. He gives half of his total stock of toffees and one extra to the first child, and then the half of the remaining stock along with one extra to the second and continues giving away in this fashion. His total stock exhausts after he takes care of 5 children. How many toffees were there in his stock initially?', 'tita', NULL, NULL, NULL, NULL, '62', 'Setting the initial stock as 64x and tracking the amount remaining after each child receives ''half plus one'', the stock exhausts exactly when x=31/32. So the initial stock = 64x = 62 toffees.', NULL, 7, 'medium', 'high', 150, 'Losing track of the ''+1 extra'' term at each halving step, which compounds across the five children.'),
  ('CAT2020_QA_S1_3', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'MOD_COUNT', 'How many 3-digit numbers are there, for which the product of their digits is more than 2 but less than 7?', 'tita', NULL, NULL, NULL, NULL, '21', 'Valid digit products are 3, 4, 5, or 6. The pattern {1,1,p} for p=3,4,5,6 gives 3 arrangements each, i.e. 12 numbers. The product 4 also arises from {2,2,1}, adding 3 more numbers. The product 6 also arises from {1,2,3}, adding 6 more (3! arrangements). Total = 12+3+6 = 21.', NULL, 7, 'medium', 'high', 150, 'Only considering the {1,1,p} digit pattern and missing the additional combinations that also give products of 4 and 6.'),
  ('CAT2020_QA_S1_4', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'ALG_EXP', 'The number of real-valued solutions of the equation 2^x + 2^(-x) = 2 - (x-2)^2 is:', 'mcq', '1', '2', 'infinite', '0', 'd', 'By AM-GM, the left side is always >= 2, with equality only at x=0. The right side is always <= 2, with equality only at x=2. Since these equality points differ, the two sides can never be equal, giving 0 solutions.', NULL, 7, 'medium', 'high', 120, 'Assuming both sides can reach their common bound of 2 at the same x-value without checking that the equality points differ.'),
  ('CAT2020_QA_S1_5', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'ALG_EXP', 'How many distinct positive integer-valued solutions exist to the equation (x^2 - 7x + 11)^(x^2-13x+42) = 1?', 'mcq', '8', '4', '2', '6', 'd', 'Solutions arise when the exponent is 0 (x=6,7), when the base is 1 (x^2-7x+10=0, giving x=2,5), or when the base is -1 with an even exponent (x^2-7x+12=0, giving x=3,4, and checking confirms the exponent is even at both). Combining all valid positive integers gives {2,3,4,5,6,7}, i.e. 6 solutions.', NULL, 8, 'high', 'high', 150, 'Forgetting to verify that the exponent is actually even in the base=-1 case before counting those x-values as valid.'),
  ('CAT2020_QA_S1_6', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'GEO_CONE', 'A solid right circular cone of height 27 cm is cut into two pieces along a plane parallel to its base at a height of 18 cm from the base. If the difference in volume of the two pieces is 225 cc, the volume, in cc, of the original cone is', 'mcq', '243', '232', '256', '264', 'a', 'The top piece is a smaller cone similar to the original, scaled by the ratio of its height (9) to the full height (27), i.e. 1/3, so its volume is (1/3)^3 = 1/27 of the full cone''s volume V. The frustum (bottom piece) has volume V - V/27 = 26V/27. The difference between the two pieces is 26V/27 - V/27 = 25V/27 = 225, giving V = 243.', NULL, 7, 'medium', 'medium', 120, 'Using the cut height (18 out of 27) as the similarity ratio for the top cone instead of the top cone''s own height (9 out of 27).'),
  ('CAT2020_QA_S1_7', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'GEO_LINE', 'The area of the region satisfying the inequalities |x| - y <= 1, y >= 0 and y <= 1 is', 'tita', NULL, NULL, NULL, NULL, '3', 'The strip 0<=y<=1 combined with |x|-y<=1 (i.e. |x|<=y+1) forms a rectangle from x=-1 to x=1 across the full height, plus two triangular extensions where |x| exceeds 1, up to |x|=2 at y=1. The rectangle contributes 2 (width 2, height 1) and the two triangles contribute 0.5 each, giving a total area of 3.', NULL, 7, 'medium', 'high', 150, 'Computing only the full outer rectangle''s area (width 4, height 1) without subtracting the excluded corner regions.'),
  ('CAT2020_QA_S1_8', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'GEO_COMP', 'On a rectangular metal sheet of area 135 sq in, a circle is painted such that the circle touches two opposite sides. If the area of the sheet left unpainted is two-thirds of the painted area then the perimeter of the rectangle in inches is', 'mcq', '3√π(5 + 12/π)', '4√π(3 + 9/π)', '3√π(5/2 + 6/π)', '5√π(3 + 9/π)', 'a', 'Let the circle''s radius be b (so the shorter side of the rectangle = 2b) and the longer side = 2l. Painted area = πb^2, and unpainted = 4lb - πb^2 = (2/3)πb^2, giving l = (5π/12)b. Using 4lb=135 to solve for b and l, and then computing the perimeter 4(l+b), gives 3√π(5+12/π).', NULL, 9, 'high', 'high', 180, 'Assuming the circle''s diameter matches the longer side of the rectangle instead of the shorter side it actually touches.'),
  ('CAT2020_QA_S1_9', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'GEO_COMP', 'A circle is inscribed in a rhombus with diagonals 12 cm and 16 cm. The ratio of the area of circle to the area of rhombus is', 'mcq', '6π/25', '5π/18', '3π/25', '2π/15', 'a', 'The rhombus side = √(6^2+8^2) = 10, and its area = (1/2)(12)(16) = 96. The inradius of a rhombus satisfies Area = 2 x side x r, so r = 96/20 = 4.8. Circle area = π(4.8)^2 = 23.04π. Ratio to rhombus area = 23.04π/96 = 6π/25.', NULL, 7, 'medium', 'medium', 150, 'Using half of a diagonal directly as the inradius instead of deriving it correctly from the area and side length.'),
  ('CAT2020_QA_S1_10', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'MOD_COUNT', 'Among 100 students, x1 have birthdays in January, x2 have birthdays in February, and so on. If x0 = max(x1, x2, ...., x12), then the smallest possible value of x0 is', 'mcq', '8', '9', '10', '12', 'b', 'To minimize the maximum, the 100 students should be distributed as evenly as possible across 12 months. Since 100/12 is about 8.33, a distribution like four months with 9 and eight months with 8 (4x9+8x8=100) is achievable, giving the smallest possible maximum as 9.', NULL, 5, 'low', 'medium', 90, 'Rounding 100/12 down to 8 and assuming the maximum could be as low as 8, which is impossible since 8x12=96<100.'),
  ('CAT2020_QA_S1_11', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'TSD_RELATIVE', 'A straight road connects points A and B. Car 1 travels from A to B and Car 2 travels from B to A, both leaving at the same time. After meeting each other, they take 45 minutes and 20 minutes, respectively, to complete their journeys. If Car 1 travels at the speed of 60 km/hr, then the speed of Car 2, in km/hr, is', 'mcq', '100', '90', '80', '70', 'b', 'For two vehicles starting simultaneously and crossing, the ratio of their speeds equals the square root of the inverse ratio of their post-crossing travel times: v1/v2 = √(t2/t1) = √(20/45) = 2/3, so v2 = 60 x (3/2) = 90.', NULL, 7, 'medium', 'high', 150, 'Inverting the square-root relation, e.g. using √(t1/t2) instead of √(t2/t1).'),
  ('CAT2020_QA_S1_12', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'PL_CP_SP', 'A person spent Rs 50000 to purchase a desktop computer and a laptop computer. He sold the desktop at 20% profit and the laptop at 10% loss. If overall he made a 2% profit then the purchase price, in rupees, of the desktop is', 'tita', NULL, NULL, NULL, NULL, '20000', 'With desktop price x and laptop price y: x+y=50000, and 1.2x+0.9y=51000 (2% profit on the total). Substituting y=50000-x and solving gives x=20000.', NULL, 5, 'medium', 'low', 120, 'Applying the 2% profit figure separately to each item instead of to the combined total spend.'),
  ('CAT2020_QA_S1_13', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'MIX_REPLACEMENT', 'A solution, of volume 40 litres, has dye and water in the proportion 2 : 3. Water is added to the solution to change this proportion to 2 : 5. If one fourths of this diluted solution is taken out, how many litres of dye must be added to the remaining solution to bring the proportion back to 2 : 3?', 'tita', NULL, NULL, NULL, NULL, '8', 'Initially dye=16 L, water=24 L. To reach 2:5 with dye still 16, water must become 40, so 16 L of water is added (total 56 L). Removing one-fourth (14 L) leaves 42 L, with dye:water still 2:5, i.e. dye=12, water=30. To restore 2:3 with water=30, dye must become 20, requiring 8 L of dye to be added.', NULL, 7, 'medium', 'medium', 150, 'Forgetting that removing a fraction of the solution keeps the ratio unchanged, and recalculating dye and water fresh.'),
  ('CAT2020_QA_S1_14', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'ALG_INDICES', 'If x = (4096)^(7+4√3), then which of the following equals to 64?', 'mcq', 'x^7/x^(2√3)', 'x^(7/2)/x^(4/√3)', 'x^(7/2)/x^(2√3)', 'x^7/x^(4√3)', 'c', 'Since 4096=2^12 and 64=2^6, we need an exponent combination on x that yields 6/[12(7+4√3)]. Testing x^(7/2)/x^(2√3), the resulting exponent simplifies using (7+4√3)(7-4√3)=49-48=1, ultimately giving exactly 2^6=64.', NULL, 8, 'high', 'high', 150, 'Not recognizing that (7+4√3)(7-4√3) simplifies to 1, which is the key step to simplify the combined exponent.'),
  ('CAT2020_QA_S1_15', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'MIX_ALLIGATION', 'An alloy is prepared by mixing three metals A, B and C in the proportion 3 : 4 : 7 by volume. Weights of the same volume of the metals A. B and C are in the ratio 5 : 2 : 6. In 130 kg of the alloy, the weight, in kg. of the metal C is', 'mcq', '48', '84', '70', '96', 'b', 'Weights are proportional to volume x density: A=3x5=15 units, B=4x2=8 units, C=7x6=42 units, totaling 65 units = 130 kg, so 1 unit = 2 kg. C''s weight = 42(2) = 84 kg.', NULL, 6, 'medium', 'medium', 150, 'Using the volume ratio directly as the weight ratio without multiplying by the given density (weight-per-volume) factors.'),
  ('CAT2020_QA_S1_16', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'ALG_HIGHER_DEGREE', 'The number of distinct real roots of the equation (x + 1/x)^2 - 3(x + 1/x) + 2 = 0 equals', 'tita', NULL, NULL, NULL, NULL, '1', 'Let a = x+1/x. Then a^2-3a+2=0 gives a=1 or a=2. For a=1, x+1/x=1 leads to x^2-x+1=0, which has no real roots. For a=2, x+1/x=2 leads to (x-1)^2=0, giving the single real root x=1. So there is 1 distinct real root overall.', NULL, 7, 'medium', 'high', 150, 'Not checking the discriminant of each resulting quadratic in x, and assuming both values of a give real solutions.'),
  ('CAT2020_QA_S1_17', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'ALG_LOG', 'If log_4 5 = (log_4 y)(log_6 √5), then y equals', 'tita', NULL, NULL, NULL, NULL, '36', 'Writing all logs in a common base and simplifying, the log_4 5 and log_4 y terms combine with the (1/2)log_6 5 factor, cancelling out the base-5 logs on both sides and leaving log y = 2 log 6 = log 36, so y = 36.', NULL, 7, 'medium', 'medium', 120, 'Mishandling the change-of-base cancellation, leaving a stray log term instead of a clean numeric answer.')
) AS v (
  external_id, year, slot, source, is_pyq,
  concept_code,
  question_text, question_type,
  option_a, option_b, option_c, option_d,
  correct_answer, solution, alternate_solution,
  difficulty, calculation_level, logic_level,
  expected_time_seconds, common_mistakes
)
JOIN subtopics s ON s.concept_code = v.concept_code
ON CONFLICT (exam_id, external_id) DO NOTHING;
